var __index = {"config":{"lang":["en"],"separator":"[\\s\\-]+","pipeline":["stopWordFilter"]},"docs":[{"location":"index.html","title":"Home","text":"<ul> <li>Inductive Bible Study Method</li> <li>The Gospel of John</li> <li>How to Take Smart Notes</li> </ul>","tags":["type-nav"]},{"location":"tags.html","title":"Tags","text":"","tags":["type-nav"]},{"location":"tags.html#tag:bible-context","title":"bible-context","text":"<ul> <li>            Galilean weddings were multi-day communal events          </li> <li>            Nazareth is &lt;10 miles from Cana, explaining Mary\u2019s connection          </li> <li>            Running out of wine would shame the family          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:bible-interpretation","title":"bible-interpretation","text":"<ul> <li>            First sign reveals Jesus\u2019 glory; disciples believe          </li> <li>            Mary's faith precedes public ministry          </li> <li>            Semi-private miracle: Glory revealed selectively          </li> <li>            Signs in the Gospel of John Lead to Faith          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:bible-observation","title":"bible-observation","text":"<ul> <li>            Jesus Reveals His Glory          </li> <li>            Jesus' First Sign was Turning Water to Wine          </li> <li>            The Wedding at Cana - Story Flow          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:bible-outline","title":"bible-outline","text":"<ul> <li>            The Gospel of John          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:clarity-of-thought","title":"clarity-of-thought","text":"<ul> <li>            How Connecting Notes Generates Insight          </li> <li>            How to Take Smart Notes          </li> <li>            Writing is Iterative          </li> <li>            Writing is Thinking          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:connections","title":"connections","text":"<ul> <li>            How Connecting Notes Generates Insight          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:iterative-process","title":"iterative-process","text":"<ul> <li>            Writing is Iterative          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:note-taking","title":"note-taking","text":"<ul> <li>            How Connecting Notes Generates Insight          </li> <li>            How to Take Smart Notes          </li> <li>            Writing is Iterative          </li> <li>            Writing is Thinking          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:source","title":"source","text":"<ul> <li>            John 1          </li> <li>            John 10          </li> <li>            John 11          </li> <li>            John 12          </li> <li>            John 13          </li> <li>            John 14          </li> <li>            John 15          </li> <li>            John 16          </li> <li>            John 17          </li> <li>            John 18          </li> <li>            John 19          </li> <li>            John 2          </li> <li>            John 20          </li> <li>            John 21          </li> <li>            John 3          </li> <li>            John 4          </li> <li>            John 5          </li> <li>            John 6          </li> <li>            John 7          </li> <li>            John 8          </li> <li>            John 9          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:source-book","title":"source-book","text":"<ul> <li>            How to Take Smart Notes          </li> <li>            The Gospel of John          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:story-flow","title":"story-flow","text":"<ul> <li>            The Wedding at Cana - Story Flow          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:the-wedding-at-cana","title":"the-wedding-at-cana","text":"<ul> <li>            First sign reveals Jesus\u2019 glory; disciples believe          </li> <li>            Galilean weddings were multi-day communal events          </li> <li>            Jesus Reveals His Glory          </li> <li>            Jesus' First Sign was Turning Water to Wine          </li> <li>            Mary's faith precedes public ministry          </li> <li>            Nazareth is &lt;10 miles from Cana, explaining Mary\u2019s connection          </li> <li>            Running out of wine would shame the family          </li> <li>            Semi-private miracle: Glory revealed selectively          </li> <li>            The Wedding at Cana - Story Flow          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:theology","title":"theology","text":"<ul> <li>            First sign reveals Jesus\u2019 glory; disciples believe          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:thinking","title":"thinking","text":"<ul> <li>            How Connecting Notes Generates Insight          </li> <li>            How to Take Smart Notes          </li> <li>            Writing is Iterative          </li> <li>            Writing is Thinking          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:type-article","title":"type-article","text":"<ul> <li>            A Voice After Silence          </li> <li>            Apply Bible study to your life          </li> <li>            Interpret what this passage means          </li> <li>            Jesus: Connecting Heaven and Earth          </li> <li>            Observe what this passage says          </li> <li>            The Lamb of God          </li> <li>            The Word Became Flesh          </li> <li>            Understanding presuppositions in Bible study          </li> <li>            Who Wrote the Gospel of John, and Why Does It Matter?          </li> <li>            Why Did James Write This Letter?          </li> <li>            Why Did John Write This Gospel?          </li> <li>            Why Did Paul Write the Letter to the Ephesians?          </li> <li>            Why Did Paul Write the Letter to the Galatians?          </li> <li>            Wrestling with John 6: The Father, the Son, and the Struggle to Believe          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:type-atomic","title":"type-atomic","text":"<ul> <li>            Atomic Notes Are Not Arguments          </li> <li>            Everything iterates          </li> <li>            First sign reveals Jesus\u2019 glory; disciples believe          </li> <li>            Galilean weddings were multi-day communal events          </li> <li>            Jesus Reveals His Glory          </li> <li>            Jesus' First Sign was Turning Water to Wine          </li> <li>            Mary's faith precedes public ministry          </li> <li>            Nazareth is &lt;10 miles from Cana, explaining Mary\u2019s connection          </li> <li>            Running out of wine would shame the family          </li> <li>            Semi-private miracle: Glory revealed selectively          </li> <li>            Signs in the Gospel of John Lead to Faith          </li> <li>            What an Atomic Note Is          </li> <li>            Zettelkasten and Inductive Bible Study          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:type-auto-moc","title":"type-auto-moc","text":"<ul> <li>            How to Take Smart Notes          </li> <li>            Inductive Bible Study Method          </li> <li>            Signs in John          </li> <li>            Zettelkasten          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:type-bible","title":"type-bible","text":"<ul> <li>            John 1          </li> <li>            John 10          </li> <li>            John 11          </li> <li>            John 12          </li> <li>            John 13          </li> <li>            John 14          </li> <li>            John 15          </li> <li>            John 16          </li> <li>            John 17          </li> <li>            John 18          </li> <li>            John 19          </li> <li>            John 2          </li> <li>            John 20          </li> <li>            John 21          </li> <li>            John 3          </li> <li>            John 4          </li> <li>            John 5          </li> <li>            John 6          </li> <li>            John 7          </li> <li>            John 8          </li> <li>            John 9          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:type-nav","title":"type-nav","text":"<ul> <li>            Home          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:type-structural","title":"type-structural","text":"<ul> <li>            The Gospel of John          </li> <li>            The Wedding at Cana - Story Flow          </li> </ul>","tags":["type-nav"]},{"location":"tags.html#tag:writing-as-thinking","title":"writing-as-thinking","text":"<ul> <li>            How Connecting Notes Generates Insight          </li> <li>            How to Take Smart Notes          </li> <li>            Writing is Iterative          </li> <li>            Writing is Thinking          </li> </ul>","tags":["type-nav"]},{"location":"Bible/John/John_01.html","title":"John 1","text":"<p>John 1:1    In the beginning was the Word, and the Word was with God, and the Word was God. John 1:2    He was with God in the beginning. John 1:3    Through Him all things were made, and without Him nothing was made that has been made. John 1:4    In Him was life, and that life was the light of men. John 1:5    The Light shines in the darkness, and the darkness has not overcome it. John 1:6    There came a man who was sent from God. His name was John. John 1:7    He came as a witness to testify about the Light, so that through him everyone might believe. John 1:8    He himself was not the Light, but he came to testify about the Light. John 1:9    The true Light, who gives light to everyone, was coming into the world. John 1:10   He was in the world, and though the world was made through Him, the world did not recognize Him. John 1:11   He came to His own, and His own did not receive Him. John 1:12   But to all who did receive Him, to those who believed in His name, He gave the right to become children of God\u2014 John 1:13   children born not of blood, nor of the desire or will of man, but born of God. John 1:14   The Word became flesh and made His dwelling among us. We have seen His glory, the glory of the one and only Son from the Father, full of grace and truth. John 1:15   John testified concerning Him. He cried out, saying, \u201cThis is He of whom I said, \u2018He who comes after me has surpassed me because He was before me.\u2019\u201d John 1:16   From His fullness we have all received grace upon grace. John 1:17   For the law was given through Moses; grace and truth came through Jesus Christ. John 1:18   No one has ever seen God, but the one and only Son, who is Himself God and is at the Father\u2019s side, has made Him known. John 1:19   And this was John\u2019s testimony when the Jews of Jerusalem sent priests and Levites to ask him, \u201cWho are you?\u201d John 1:20   He did not refuse to confess, but openly declared, \u201cI am not the Christ.\u201d John 1:21   \u201cThen who are you?\u201d they inquired. \u201cAre you Elijah?\u201d He said, \u201cI am not.\u201d \u201cAre you the Prophet?\u201d He answered, \u201cNo.\u201d John 1:22   So they said to him, \u201cWho are you? We need an answer for those who sent us. What do you say about yourself?\u201d John 1:23   John replied in the words of Isaiah the prophet: \u201cI am a voice of one calling in the wilderness, \u2018Make straight the way for the Lord.\u2019\u201d John 1:24   Then the Pharisees who had been sent John 1:25   asked him, \u201cWhy then do you baptize, if you are not the Christ, nor Elijah, nor the Prophet?\u201d John 1:26   \u201cI baptize with water,\u201d John replied, \u201cbut among you stands One you do not know. John 1:27   He is the One who comes after me, the straps of whose sandals I am not worthy to untie.\u201d John 1:28   All this happened at Bethany beyond the Jordan, where John was baptizing. John 1:29   The next day John saw Jesus coming toward him and said, \u201cLook, the Lamb of God, who takes away the sin of the world! John 1:30   This is He of whom I said, \u2018A man who comes after me has surpassed me because He was before me.\u2019 John 1:31   I myself did not know Him, but the reason I came baptizing with water was that He might be revealed to Israel.\u201d John 1:32   Then John testified, \u201cI saw the Spirit descending from heaven like a dove and resting on Him. John 1:33   I myself did not know Him, but the One who sent me to baptize with water told me, \u2018The man on whom you see the Spirit descend and rest is He who will baptize with the Holy Spirit.\u2019 John 1:34   I have seen and testified that this is the Son of God.\u201d John 1:35   The next day John was there again with two of his disciples. John 1:36   When he saw Jesus walking by, he said, \u201cLook, the Lamb of God!\u201d John 1:37   And when the two disciples heard him say this, they followed Jesus. John 1:38   Jesus turned and saw them following. \u201cWhat do you want?\u201d He asked. They said to Him, \u201cRabbi\u201d (which means Teacher), \u201cwhere are You staying?\u201d John 1:39   \u201cCome and see,\u201d He replied. So they went and saw where He was staying, and spent that day with Him. It was about the tenth hour. John 1:40   Andrew, Simon Peter\u2019s brother, was one of the two who heard John\u2019s testimony and followed Jesus. John 1:41   He first found his brother Simon and told him, \u201cWe have found the Messiah\u201d (which is translated as Christ). John 1:42   Andrew brought him to Jesus, who looked at him and said, \u201cYou are Simon son of John. You will be called Cephas\u201d (which is translated as Peter). John 1:43   The next day Jesus decided to set out for Galilee. Finding Philip, He told him, \u201cFollow Me.\u201d John 1:44   Now Philip was from Bethsaida, the same town as Andrew and Peter. John 1:45   Philip found Nathanael and told him, \u201cWe have found the One Moses wrote about in the Law, the One the prophets foretold\u2014Jesus of Nazareth, the son of Joseph.\u201d John 1:46   \u201cCan anything good come from Nazareth?\u201d Nathanael asked. \u201cCome and see,\u201d said Philip. John 1:47   When Jesus saw Nathanael approaching, He said of him, \u201cHere is a true Israelite, in whom there is no deceit.\u201d John 1:48   \u201cHow do You know me?\u201d Nathanael asked. Jesus replied, \u201cBefore Philip called you, I saw you under the fig tree.\u201d John 1:49   \u201cRabbi,\u201d Nathanael answered, \u201cYou are the Son of God! You are the King of Israel!\u201d John 1:50   Jesus said to him, \u201cDo you believe just because I told you I saw you under the fig tree? You will see greater things than these.\u201d John 1:51   Then He declared, \u201cTruly, truly, I tell you, you will all see heaven open and the angels of God ascending and descending on the Son of Man.\u201d</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_01.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_02.html","title":"John 2","text":"<p>John 2:1    On the third day a wedding took place at Cana in Galilee. Jesus\u2019 mother was there, John 2:2    and Jesus and His disciples had also been invited to the wedding. John 2:3    When the wine ran out, Jesus\u2019 mother said to Him, \u201cThey have no more wine.\u201d John 2:4    \u201cWoman, what is that to you and to Me?\u201d Jesus replied. \u201cMy hour has not yet come.\u201d John 2:5    His mother said to the servants, \u201cDo whatever He tells you.\u201d John 2:6    Now six stone water jars had been set there for the Jewish rites of purification. Each could hold from twenty to thirty gallons. John 2:7    Jesus told the servants, \u201cFill the jars with water.\u201d So they filled them to the brim. John 2:8    \u201cNow draw some out,\u201d He said, \u201cand take it to the master of the banquet.\u201d They did so, John 2:9    and the master of the banquet tasted the water that had been turned into wine. He did not know where it was from, but the servants who had drawn the water knew. Then he called the bridegroom aside John 2:10   and said, \u201cEveryone serves the fine wine first, and then the cheap wine after the guests are drunk. But you have saved the fine wine until now!\u201d John 2:11   Jesus performed this, the first of His signs, at Cana in Galilee. He thus revealed His glory, and His disciples believed in Him. John 2:12   After this, He went down to Capernaum with His mother and brothers and His disciples, and they stayed there a few days. John 2:13   When the Jewish Passover was near, Jesus went up to Jerusalem. John 2:14   In the temple courts He found men selling cattle, sheep, and doves, and money changers seated at their tables. John 2:15   So He made a whip out of cords and drove all from the temple courts, both sheep and cattle. He poured out the coins of the money changers and overturned their tables. John 2:16   To those selling doves He said, \u201cGet these out of here! How dare you turn My Father\u2019s house into a marketplace!\u201d John 2:17   His disciples remembered that it is written: \u201cZeal for Your house will consume Me.\u201d John 2:18   On account of this, the Jews demanded, \u201cWhat sign can You show us to prove Your authority to do these things?\u201d John 2:19   Jesus answered, \u201cDestroy this temple, and in three days I will raise it up again.\u201d John 2:20   \u201cThis temple took forty-six years to build,\u201d the Jews replied, \u201cand You are going to raise it up in three days?\u201d John 2:21   But Jesus was speaking about the temple of His body. John 2:22   After He was raised from the dead, His disciples remembered that He had said this. Then they believed the Scripture and the word that Jesus had spoken. John 2:23   While He was in Jerusalem at the Passover Feast, many people saw the signs He was doing and believed in His name. John 2:24   But Jesus did not entrust Himself to them, for He knew them all. John 2:25   He did not need any testimony about man, for He knew what was in a man.</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_02.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_03.html","title":"John 3","text":"<p>John 3:1    Now there was a man of the Pharisees named Nicodemus, a leader of the Jews. John 3:2    He came to Jesus at night and said, \u201cRabbi, we know that You are a teacher who has come from God. For no one could perform the signs You are doing if God were not with him.\u201d John 3:3    Jesus replied, \u201cTruly, truly, I tell you, no one can see the kingdom of God unless he is born again.\u201d John 3:4    \u201cHow can a man be born when he is old?\u201d Nicodemus asked. \u201cCan he enter his mother\u2019s womb a second time to be born?\u201d John 3:5    Jesus answered, \u201cTruly, truly, I tell you, no one can enter the kingdom of God unless he is born of water and the Spirit. John 3:6    Flesh is born of flesh, but spirit is born of the Spirit. John 3:7    Do not be amazed that I said, \u2018You must be born again.\u2019 John 3:8    The wind blows where it wishes. You hear its sound, but you do not know where it comes from or where it is going. So it is with everyone born of the Spirit.\u201d John 3:9    \u201cHow can this be?\u201d Nicodemus asked. John 3:10   \u201cYou are Israel\u2019s teacher,\u201d said Jesus, \u201cand you do not understand these things? John 3:11   Truly, truly, I tell you, we speak of what we know, and we testify to what we have seen, and yet you people do not accept our testimony. John 3:12   If I have told you about earthly things and you do not believe, how will you believe if I tell you about heavenly things? John 3:13   No one has ascended into heaven except the One who descended from heaven\u2014the Son of Man. John 3:14   Just as Moses lifted up the snake in the wilderness, so the Son of Man must be lifted up, John 3:15   that everyone who believes in Him may have eternal life. John 3:16   For God so loved the world that He gave His one and only Son, that everyone who believes in Him shall not perish but have eternal life. John 3:17   For God did not send His Son into the world to condemn the world, but to save the world through Him. John 3:18   Whoever believes in Him is not condemned, but whoever does not believe has already been condemned, because he has not believed in the name of God\u2019s one and only Son. John 3:19   And this is the verdict: The Light has come into the world, but men loved the darkness rather than the Light because their deeds were evil. John 3:20   Everyone who does evil hates the Light, and does not come into the Light for fear that his deeds will be exposed. John 3:21   But whoever practices the truth comes into the Light, so that it may be seen clearly that what he has done has been accomplished in God.\u201d John 3:22   After this, Jesus and His disciples went into the Judean countryside, where He spent some time with them and baptized. John 3:23   Now John was also baptizing at Aenon near Salim, because the water was plentiful there, and people kept coming to be baptized. John 3:24   (For John had not yet been thrown into prison.) John 3:25   Then a dispute arose between John\u2019s disciples and a certain Jew over the issue of ceremonial washing. John 3:26   So John\u2019s disciples came to him and said, \u201cLook, Rabbi, the One who was with you beyond the Jordan, the One you testified about\u2014He is baptizing, and everyone is going to Him.\u201d John 3:27   John replied, \u201cA man can receive only what is given him from heaven. John 3:28   You yourselves can testify that I said, \u2018I am not the Christ, but am sent ahead of Him.\u2019 John 3:29   The bride belongs to the bridegroom. The friend of the bridegroom stands and listens for him, and is overjoyed to hear the bridegroom\u2019s voice. That joy is mine, and it is now complete. John 3:30   He must increase; I must decrease. John 3:31   The One who comes from above is above all. The one who is from the earth belongs to the earth and speaks as one from the earth. The One who comes from heaven is above all. John 3:32   He testifies to what He has seen and heard, yet no one accepts His testimony. John 3:33   Whoever accepts His testimony has certified that God is truthful. John 3:34   For the One whom God has sent speaks the words of God, for God gives the Spirit without limit. John 3:35   The Father loves the Son and has placed all things in His hands. John 3:36   Whoever believes in the Son has eternal life. Whoever rejects the Son will not see life. Instead, the wrath of God remains on him.\u201d</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_03.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_04.html","title":"John 4","text":"<p>John 4:1    When Jesus realized that the Pharisees were aware He was gaining and baptizing more disciples than John John 4:2    (although it was not Jesus who baptized, but His disciples), John 4:3    He left Judea and returned to Galilee. John 4:4    Now He had to pass through Samaria. John 4:5    So He came to a town of Samaria called Sychar, near the plot of ground that Jacob had given to his son Joseph. John 4:6    Since Jacob\u2019s well was there, Jesus, weary from His journey, sat down by the well. It was about the sixth hour. John 4:7    When a Samaritan woman came to draw water, Jesus said to her, \u201cGive Me a drink.\u201d John 4:8    (His disciples had gone into the town to buy food.) John 4:9    \u201cYou are a Jew,\u201d said the woman. \u201cHow can You ask for a drink from me, a Samaritan woman?\u201d (For Jews do not associate with Samaritans.) John 4:10   Jesus answered, \u201cIf you knew the gift of God and who is asking you for a drink, you would have asked Him, and He would have given you living water.\u201d John 4:11   \u201cSir,\u201d the woman replied, \u201cYou have nothing to draw with and the well is deep. Where then will You get this living water? John 4:12   Are You greater than our father Jacob, who gave us this well and drank from it himself, as did his sons and his livestock?\u201d John 4:13   Jesus said to her, \u201cEveryone who drinks this water will be thirsty again. John 4:14   But whoever drinks the water I give him will never thirst. Indeed, the water I give him will become in him a fount of water springing up to eternal life.\u201d John 4:15   The woman said to Him, \u201cSir, give me this water so that I will not get thirsty and have to keep coming here to draw water.\u201d John 4:16   Jesus told her, \u201cGo, call your husband and come back.\u201d John 4:17   \u201cI have no husband,\u201d the woman replied. Jesus said to her, \u201cYou are correct to say that you have no husband. John 4:18   In fact, you have had five husbands, and the man you now have is not your husband. You have spoken truthfully.\u201d John 4:19   \u201cSir,\u201d the woman said, \u201cI see that You are a prophet. John 4:20   Our fathers worshiped on this mountain, but you Jews say that the place where one must worship is in Jerusalem.\u201d John 4:21   \u201cBelieve Me, woman,\u201d Jesus replied, \u201ca time is coming when you will worship the Father neither on this mountain nor in Jerusalem. John 4:22   You worship what you do not know; we worship what we do know, for salvation is from the Jews. John 4:23   But a time is coming and has now come when the true worshipers will worship the Father in spirit and in truth, for the Father is seeking such as these to worship Him. John 4:24   God is Spirit, and His worshipers must worship Him in spirit and in truth.\u201d John 4:25   The woman said, \u201cI know that Messiah\u201d (called Christ) \u201cis coming. When He comes, He will explain everything to us.\u201d John 4:26   Jesus answered, \u201cI who speak to you am He.\u201d John 4:27   Just then His disciples returned and were surprised that He was speaking with a woman. But no one asked Him, \u201cWhat do You want from her?\u201d or \u201cWhy are You talking with her?\u201d John 4:28   Then the woman left her water jar, went back into the town, and said to the people, John 4:29   \u201cCome, see a man who told me everything I ever did. Could this be the Christ?\u201d John 4:30   So they left the town and made their way toward Jesus. John 4:31   Meanwhile the disciples urged Him, \u201cRabbi, eat something.\u201d John 4:32   But He told them, \u201cI have food to eat that you know nothing about.\u201d John 4:33   So the disciples asked one another, \u201cCould someone have brought Him food?\u201d John 4:34   Jesus explained, \u201cMy food is to do the will of Him who sent Me and to finish His work. John 4:35   Do you not say, \u2018There are still four months until the harvest\u2019? I tell you, lift up your eyes and look at the fields, for they are ripe for harvest. John 4:36   Already the reaper draws his wages and gathers a crop for eternal life, so that the sower and the reaper may rejoice together. John 4:37   For in this case the saying \u2018One sows and another reaps\u2019 is true. John 4:38   I sent you to reap what you have not worked for; others have done the hard work, and now you have taken up their labor.\u201d John 4:39   Many of the Samaritans from that town believed in Jesus because of the woman\u2019s testimony, \u201cHe told me everything I ever did.\u201d John 4:40   So when the Samaritans came to Him, they asked Him to stay with them, and He stayed two days. John 4:41   And many more believed because of His message. John 4:42   They said to the woman, \u201cWe now believe not only because of your words; we have heard for ourselves, and we know that this man truly is the Savior of the world.\u201d John 4:43   After two days, Jesus left for Galilee. John 4:44   Now He Himself had testified that a prophet has no honor in his own hometown. John 4:45   Yet when He arrived, the Galileans welcomed Him. They had seen all the great things He had done in Jerusalem at the feast, for they had gone there as well. John 4:46   So once again He came to Cana in Galilee, where He had turned the water into wine. And there was a royal official whose son lay sick at Capernaum. John 4:47   When he heard that Jesus had come from Judea to Galilee, he went and begged Him to come down and heal his son, who was about to die. John 4:48   Jesus said to him, \u201cUnless you people see signs and wonders, you will never believe.\u201d John 4:49   \u201cSir,\u201d the official said, \u201ccome down before my child dies.\u201d John 4:50   \u201cGo,\u201d said Jesus. \u201cYour son will live.\u201d The man took Jesus at His word and departed. John 4:51   And while he was still on the way, his servants met him with the news that his boy was alive. John 4:52   So he inquired as to the hour when his son had recovered, and they told him, \u201cThe fever left him yesterday at the seventh hour.\u201d John 4:53   Then the father realized that this was the very hour in which Jesus had told him, \u201cYour son will live.\u201d And he and all his household believed. John 4:54   This was now the second sign that Jesus performed after coming from Judea into Galilee.</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_04.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_05.html","title":"John 5","text":"<p>John 5:1    Some time later there was a feast of the Jews, and Jesus went up to Jerusalem. John 5:2    Now there is in Jerusalem near the Sheep Gate a pool with five covered colonnades, which in Hebrew is called Bethesda. John 5:3    On these walkways lay a great number of the sick, the blind, the lame, and the paralyzed. John 5:4   John 5:5    One man there had been an invalid for thirty-eight years. John 5:6    When Jesus saw him lying there and realized that he had spent a long time in this condition, He asked him, \u201cDo you want to get well?\u201d John 5:7    \u201cSir,\u201d the invalid replied, \u201cI have no one to help me into the pool when the water is stirred. While I am on my way, someone else goes in before me.\u201d John 5:8    Then Jesus told him, \u201cGet up, pick up your mat, and walk.\u201d John 5:9    Immediately the man was made well, and he picked up his mat and began to walk. Now this happened on the Sabbath day, John 5:10   so the Jews said to the man who had been healed, \u201cThis is the Sabbath! It is unlawful for you to carry your mat.\u201d John 5:11   But he answered, \u201cThe man who made me well told me, \u2018Pick up your mat and walk.\u2019\u201d John 5:12   \u201cWho is this man who told you to pick it up and walk?\u201d they asked. John 5:13   But the man who was healed did not know who it was, for Jesus had slipped away while the crowd was there. John 5:14   Afterward, Jesus found the man at the temple and said to him, \u201cSee, you have been made well. Stop sinning, or something worse may happen to you.\u201d John 5:15   And the man went away and told the Jews that it was Jesus who had made him well. John 5:16   Now because Jesus was doing these things on the Sabbath, the Jews began to persecute Him. John 5:17   But Jesus answered them, \u201cTo this very day My Father is at His work, and I too am working.\u201d John 5:18   Because of this, the Jews tried all the harder to kill Him. Not only was He breaking the Sabbath, but He was even calling God His own Father, making Himself equal with God. John 5:19   So Jesus replied, \u201cTruly, truly, I tell you, the Son can do nothing by Himself, unless He sees the Father doing it. For whatever the Father does, the Son also does. John 5:20   The Father loves the Son and shows Him all He does. And to your amazement, He will show Him even greater works than these. John 5:21   For just as the Father raises the dead and gives them life, so also the Son gives life to whom He wishes. John 5:22   Furthermore, the Father judges no one, but has assigned all judgment to the Son, John 5:23   so that all may honor the Son just as they honor the Father. Whoever does not honor the Son does not honor the Father who sent Him. John 5:24   Truly, truly, I tell you, whoever hears My word and believes Him who sent Me has eternal life and will not come under judgment. Indeed, he has crossed over from death to life. John 5:25   Truly, truly, I tell you, the hour is coming and has now come when the dead will hear the voice of the Son of God, and those who hear will live. John 5:26   For as the Father has life in Himself, so also He has granted the Son to have life in Himself. John 5:27   And He has given Him authority to execute judgment, because He is the Son of Man. John 5:28   Do not be amazed at this, for the hour is coming when all who are in their graves will hear His voice John 5:29   and come out\u2014those who have done good to the resurrection of life, and those who have done evil to the resurrection of judgment. John 5:30   I can do nothing by Myself; I judge only as I hear. And My judgment is just, because I do not seek My own will, but the will of Him who sent Me. John 5:31   If I testify about Myself, My testimony is not valid. John 5:32   There is another who testifies about Me, and I know that His testimony about Me is valid. John 5:33   You have sent to John, and he has testified to the truth. John 5:34   Even though I do not accept human testimony, I say these things so that you may be saved. John 5:35   John was a lamp that burned and gave light, and you were willing for a season to bask in his light. John 5:36   But I have testimony more substantial than that of John. For the works that the Father has given Me to accomplish\u2014the very works I am doing\u2014testify about Me that the Father has sent Me. John 5:37   And the Father who sent Me has Himself testified about Me. You have never heard His voice nor seen His form, John 5:38   nor does His word abide in you, because you do not believe the One He sent. John 5:39   You pore over the Scriptures because you presume that by them you possess eternal life. These are the very words that testify about Me, John 5:40   yet you refuse to come to Me to have life. John 5:41   I do not accept glory from men, John 5:42   but I know you, that you do not have the love of God within you. John 5:43   I have come in My Father\u2019s name, and you have not received Me; but if someone else comes in his own name, you will receive him. John 5:44   How can you believe if you accept glory from one another, yet do not seek the glory that comes from the only God? John 5:45   Do not think that I will accuse you before the Father. Your accuser is Moses, in whom you have put your hope. John 5:46   If you had believed Moses, you would believe Me, because he wrote about Me. John 5:47   But since you do not believe what he wrote, how will you believe what I say?\u201d</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_05.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_06.html","title":"John 6","text":"<p>John 6:1    After this, Jesus crossed to the other side of the Sea of Galilee (that is, the Sea of Tiberias). John 6:2    A large crowd followed Him because they saw the signs He was performing on the sick. John 6:3    Then Jesus went up on the mountain and sat down with His disciples. John 6:4    Now the Jewish Feast of the Passover was near. John 6:5    When Jesus looked up and saw a large crowd coming toward Him, He said to Philip, \u201cWhere can we buy bread for these people to eat?\u201d John 6:6    But He was asking this to test him, for He knew what He was about to do. John 6:7    Philip answered, \u201cTwo hundred denarii would not buy enough bread for each of them to have a small piece.\u201d John 6:8    One of His disciples, Andrew, Simon Peter\u2019s brother, said to Him, John 6:9    \u201cHere is a boy with five barley loaves and two small fish. But what difference will these make among so many?\u201d John 6:10   \u201cHave the people sit down,\u201d Jesus said. Now there was plenty of grass in that place, so the men sat down, about five thousand of them. John 6:11   Then Jesus took the loaves and the fish, gave thanks, and distributed to those who were seated as much as they wanted. John 6:12   And when everyone was full, He said to His disciples, \u201cGather the pieces that are left over, so that nothing will be wasted.\u201d John 6:13   So they collected them and filled twelve baskets with the pieces of the five barley loaves left over by those who had eaten. John 6:14   When the people saw the sign that Jesus had performed, they began to say, \u201cTruly this is the Prophet who is to come into the world.\u201d John 6:15   Then Jesus, realizing that they were about to come and make Him king by force, withdrew again to a mountain by Himself. John 6:16   When evening came, His disciples went down to the sea, John 6:17   got into a boat, and started across the sea to Capernaum. It was already dark, and Jesus had not yet gone out to them. John 6:18   A strong wind was blowing, and the sea grew agitated. John 6:19   When they had rowed about three or four miles, they saw Jesus approaching the boat, walking on the sea\u2014and they were terrified. John 6:20   But Jesus spoke up: \u201cIt is I; do not be afraid.\u201d John 6:21   Then they were willing to take Him into the boat, and at once the boat reached the shore where they were heading. John 6:22   The next day, the crowd that had remained on the other side of the sea realized that only one boat had been there, and that Jesus had not boarded it with His disciples, but they had gone away alone. John 6:23   However, some boats from Tiberias landed near the place where the people had eaten the bread after the Lord had given thanks. John 6:24   So when the crowd saw that neither Jesus nor His disciples were there, they got into the boats and went to Capernaum to look for Him. John 6:25   When they found Him on the other side of the sea, they asked Him, \u201cRabbi, when did You get here?\u201d John 6:26   Jesus replied, \u201cTruly, truly, I tell you, it is not because you saw these signs that you are looking for Me, but because you ate the loaves and had your fill. John 6:27   Do not work for food that perishes, but for food that endures to eternal life, which the Son of Man will give you. For on Him God the Father has placed His seal of approval.\u201d John 6:28   Then they inquired, \u201cWhat must we do to perform the works of God?\u201d John 6:29   Jesus replied, \u201cThe work of God is this: to believe in the One He has sent.\u201d John 6:30   So they asked Him, \u201cWhat sign then will You perform, so that we may see it and believe You? What will You do? John 6:31   Our fathers ate the manna in the wilderness, as it is written: \u2018He gave them bread from heaven to eat.\u2019\u201d John 6:32   Jesus said to them, \u201cTruly, truly, I tell you, it was not Moses who gave you the bread from heaven, but it is My Father who gives you the true bread from heaven. John 6:33   For the bread of God is He who comes down from heaven and gives life to the world.\u201d John 6:34   \u201cSir,\u201d they said, \u201cgive us this bread at all times.\u201d John 6:35   Jesus answered, \u201cI am the bread of life. Whoever comes to Me will never hunger, and whoever believes in Me will never thirst. John 6:36   But as I stated, you have seen Me and still you do not believe. John 6:37   Everyone the Father gives Me will come to Me, and the one who comes to Me I will never drive away. John 6:38   For I have come down from heaven, not to do My own will, but to do the will of Him who sent Me. John 6:39   And this is the will of Him who sent Me, that I shall lose none of those He has given Me, but raise them up at the last day. John 6:40   For it is My Father\u2019s will that everyone who looks to the Son and believes in Him shall have eternal life, and I will raise him up at the last day.\u201d John 6:41   At this, the Jews began to grumble about Jesus because He had said, \u201cI am the bread that came down from heaven.\u201d John 6:42   They were asking, \u201cIs this not Jesus, the son of Joseph, whose father and mother we know? How then can He say, \u2018I have come down from heaven?\u2019\u201d John 6:43   \u201cStop grumbling among yourselves,\u201d Jesus replied. John 6:44   \u201cNo one can come to Me unless the Father who sent Me draws him, and I will raise him up at the last day. John 6:45   It is written in the Prophets: \u2018And they will all be taught by God.\u2019 Everyone who has heard the Father and learned from Him comes to Me\u2014 John 6:46   not that anyone has seen the Father except the One who is from God; only He has seen the Father. John 6:47   Truly, truly, I tell you, he who believes has eternal life. John 6:48   I am the bread of life. John 6:49   Your fathers ate the manna in the wilderness, yet they died. John 6:50   This is the bread that comes down from heaven, so that anyone may eat of it and not die. John 6:51   I am the living bread that came down from heaven. If anyone eats of this bread, he will live forever. And this bread, which I will give for the life of the world, is My flesh.\u201d John 6:52   At this, the Jews began to argue among themselves, \u201cHow can this man give us His flesh to eat?\u201d John 6:53   So Jesus said to them, \u201cTruly, truly, I tell you, unless you eat the flesh and drink the blood of the Son of Man, you have no life in you. John 6:54   Whoever eats My flesh and drinks My blood has eternal life, and I will raise him up at the last day. John 6:55   For My flesh is real food, and My blood is real drink. John 6:56   Whoever eats My flesh and drinks My blood remains in Me, and I in him. John 6:57   Just as the living Father sent Me and I live because of the Father, so also the one who feeds on Me will live because of Me. John 6:58   This is the bread that came down from heaven. Unlike your fathers, who ate the manna and died, the one who eats this bread will live forever.\u201d John 6:59   Jesus said this while teaching in the synagogue in Capernaum. John 6:60   On hearing it, many of His disciples said, \u201cThis is a difficult teaching. Who can accept it?\u201d John 6:61   Aware that His disciples were grumbling about this teaching, Jesus asked them, \u201cDoes this offend you? John 6:62   Then what will happen if you see the Son of Man ascend to where He was before? John 6:63   The Spirit gives life; the flesh profits nothing. The words I have spoken to you are spirit and they are life. John 6:64   However, there are some of you who do not believe.\u201d (For Jesus had known from the beginning which of them did not believe and who would betray Him.) John 6:65   Then Jesus said, \u201cThis is why I told you that no one can come to Me unless the Father has granted it to him.\u201d John 6:66   From that time on many of His disciples turned back and no longer walked with Him. John 6:67   So Jesus asked the Twelve, \u201cDo you want to leave too?\u201d John 6:68   Simon Peter replied, \u201cLord, to whom would we go? You have the words of eternal life. John 6:69   We believe and know that You are the Holy One of God.\u201d John 6:70   Jesus answered them, \u201cHave I not chosen you, the Twelve? Yet one of you is a devil!\u201d John 6:71   He was speaking about Judas, the son of Simon Iscariot. For although Judas was one of the Twelve, he was later to betray Jesus.</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_06.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_07.html","title":"John 7","text":"<p>John 7:1    After this, Jesus traveled throughout Galilee. He did not want to travel in Judea, because the Jews there were trying to kill Him. John 7:2    However, the Jewish Feast of Tabernacles was near. John 7:3    So Jesus\u2019 brothers said to Him, \u201cLeave here and go to Judea, so that Your disciples there may see the works You are doing. John 7:4    For no one who wants to be known publicly acts in secret. Since You are doing these things, show Yourself to the world.\u201d John 7:5    For even His own brothers did not believe in Him. John 7:6    Therefore Jesus told them, \u201cAlthough your time is always at hand, My time has not yet come. John 7:7    The world cannot hate you, but it hates Me, because I testify that its works are evil. John 7:8    Go up to the feast on your own. I am not going up to this feast, because My time has not yet come.\u201d John 7:9    Having said this, Jesus remained in Galilee. John 7:10   But after His brothers had gone up to the feast, He also went\u2014not publicly, but in secret. John 7:11   So the Jews were looking for Him at the feast and asking, \u201cWhere is He?\u201d John 7:12   Many in the crowds were whispering about Him. Some said, \u201cHe is a good man.\u201d But others replied, \u201cNo, He deceives the people.\u201d John 7:13   Yet no one would speak publicly about Him for fear of the Jews. John 7:14   About halfway through the feast, Jesus went up to the temple courts and began to teach. John 7:15   The Jews were amazed and asked, \u201cHow did this man attain such learning without having studied?\u201d John 7:16   \u201cMy teaching is not My own,\u201d Jesus replied. \u201cIt comes from Him who sent Me. John 7:17   If anyone desires to do His will, he will know whether My teaching is from God or whether I speak on My own. John 7:18   He who speaks on his own authority seeks his own glory, but He who seeks the glory of the One who sent Him is a man of truth; in Him there is no falsehood. John 7:19   Has not Moses given you the law? Yet not one of you keeps it. Why are you trying to kill Me?\u201d John 7:20   \u201cYou have a demon,\u201d the crowd replied. \u201cWho is trying to kill You?\u201d John 7:21   Jesus answered them, \u201cI did one miracle, and you are all amazed. John 7:22   But because Moses gave you circumcision, you circumcise a boy on the Sabbath (not that it is from Moses, but from the patriarchs.) John 7:23   If a boy can be circumcised on the Sabbath so that the law of Moses will not be broken, why are you angry with Me for making the whole man well on the Sabbath? John 7:24   Stop judging by outward appearances, and start judging justly.\u201d John 7:25   Then some of the people of Jerusalem began to say, \u201cIsn\u2019t this the man they are trying to kill? John 7:26   Yet here He is, speaking publicly, and they are not saying anything to Him. Have the rulers truly recognized that this is the Christ? John 7:27   But we know where this man is from. When the Christ comes, no one will know where He is from.\u201d John 7:28   Then Jesus, still teaching in the temple courts, cried out, \u201cYou know Me, and you know where I am from. I have not come of My own accord, but He who sent Me is true. You do not know Him, John 7:29   but I know Him, because I am from Him and He sent Me.\u201d John 7:30   So they tried to seize Him, but no one laid a hand on Him, because His hour had not yet come. John 7:31   Many in the crowd, however, believed in Him and said, \u201cWhen the Christ comes, will He perform more signs than this man?\u201d John 7:32   When the Pharisees heard the crowd whispering these things about Jesus, they and the chief priests sent officers to arrest Him. John 7:33   So Jesus said, \u201cI am with you only a little while longer, and then I am going to the One who sent Me. John 7:34   You will look for Me, but you will not find Me; and where I am, you cannot come.\u201d John 7:35   At this, the Jews said to one another, \u201cWhere does He intend to go that we will not find Him? Will He go where the Jews are dispersed among the Greeks, and teach the Greeks? John 7:36   What does He mean by saying, \u2018You will look for Me, but you will not find Me,\u2019 and, \u2018Where I am, you cannot come\u2019?\u201d John 7:37   On the last and greatest day of the feast, Jesus stood up and called out in a loud voice, \u201cIf anyone is thirsty, let him come to Me and drink. John 7:38   Whoever believes in Me, as the Scripture has said: \u2018Streams of living water will flow from within him.\u2019\u201d John 7:39   He was speaking about the Spirit, whom those who believed in Him were later to receive. For the Spirit had not yet been given, because Jesus had not yet been glorified. John 7:40   On hearing these words, some of the people said, \u201cThis is truly the Prophet.\u201d John 7:41   Others declared, \u201cThis is the Christ.\u201d But still others asked, \u201cHow can the Christ come from Galilee? John 7:42   Doesn\u2019t the Scripture say that the Christ will come from the line of David and from Bethlehem, the village where David lived?\u201d John 7:43   So there was division in the crowd because of Jesus. John 7:44   Some of them wanted to seize Him, but no one laid a hand on Him. John 7:45   Then the officers returned to the chief priests and Pharisees, who asked them, \u201cWhy didn\u2019t you bring Him in?\u201d John 7:46   \u201cNever has anyone spoken like this man!\u201d the officers answered. John 7:47   \u201cHave you also been deceived?\u201d replied the Pharisees. John 7:48   \u201cHave any of the rulers or Pharisees believed in Him? John 7:49   But this crowd that does not know the law\u2014they are under a curse.\u201d John 7:50   Nicodemus, who had gone to Jesus earlier and who himself was one of them, asked, John 7:51   \u201cDoes our law convict a man without first hearing from him to determine what he has done?\u201d John 7:52   \u201cAren\u2019t you also from Galilee?\u201d they replied. \u201cLook into it, and you will see that no prophet comes out of Galilee.\u201d John 7:53   Then each went to his own home.</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_07.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_08.html","title":"John 8","text":"<p>John 8:1    But Jesus went to the Mount of Olives. John 8:2    Early in the morning He went back into the temple courts. All the people came to Him, and He sat down to teach them. John 8:3    The scribes and Pharisees, however, brought to Him a woman caught in adultery. They made her stand before them John 8:4    and said, \u201cTeacher, this woman was caught in the act of adultery. John 8:5    In the Law Moses commanded us to stone such a woman. So what do You say?\u201d John 8:6    They said this to test Him, in order to have a basis for accusing Him. But Jesus bent down and began to write on the ground with His finger. John 8:7    When they continued to question Him, He straightened up and said to them, \u201cLet him who is without sin among you be the first to cast a stone at her.\u201d John 8:8    And again He bent down and wrote on the ground. John 8:9    When they heard this, they began to go away one by one, beginning with the older ones, until only Jesus was left, with the woman standing there. John 8:10   Then Jesus straightened up and asked her, \u201cWoman, where are your accusers? Has no one condemned you?\u201d John 8:11   \u201cNo one, Lord,\u201d she answered. \u201cThen neither do I condemn you,\u201d Jesus declared. \u201cNow go and sin no more.\u201d John 8:12   Once again, Jesus spoke to the people and said, \u201cI am the light of the world. Whoever follows Me will never walk in the darkness, but will have the light of life.\u201d John 8:13   So the Pharisees said to Him, \u201cYou are testifying about Yourself; Your testimony is not valid.\u201d John 8:14   Jesus replied, \u201cEven if I testify about Myself, My testimony is valid, because I know where I came from and where I am going. But you do not know where I came from or where I am going. John 8:15   You judge according to the flesh; I judge no one. John 8:16   But even if I do judge, My judgment is true, because I am not alone; I am with the Father who sent Me. John 8:17   Even in your own Law it is written that the testimony of two men is valid. John 8:18   I am One who testifies about Myself, and the Father, who sent Me, also testifies about Me.\u201d John 8:19   \u201cWhere is Your Father?\u201d they asked Him. \u201cYou do not know Me or My Father,\u201d Jesus answered. \u201cIf you knew Me, you would know My Father as well.\u201d John 8:20   He spoke these words while teaching in the temple courts, near the treasury. Yet no one seized Him, because His hour had not yet come. John 8:21   Again He said to them, \u201cI am going away, and you will look for Me, but you will die in your sin. Where I am going, you cannot come.\u201d John 8:22   So the Jews began to ask, \u201cWill He kill Himself, since He says, \u2018Where I am going, you cannot come\u2019?\u201d John 8:23   Then He told them, \u201cYou are from below; I am from above. You are of this world; I am not of this world. John 8:24   That is why I told you that you would die in your sins. For unless you believe that I am He, you will die in your sins.\u201d John 8:25   \u201cWho are You?\u201d they asked. \u201cJust what I have been telling you from the beginning,\u201d Jesus replied. John 8:26   \u201cI have much to say about you and much to judge. But the One who sent Me is truthful, and what I have heard from Him, I tell the world.\u201d John 8:27   They did not understand that He was telling them about the Father. John 8:28   So Jesus said, \u201cWhen you have lifted up the Son of Man, then you will know that I am He, and that I do nothing on My own, but speak exactly what the Father has taught Me. John 8:29   He who sent Me is with Me. He has not left Me alone, because I always do what pleases Him.\u201d John 8:30   As Jesus spoke these things, many believed in Him. John 8:31   So He said to the Jews who had believed Him, \u201cIf you continue in My word, you are truly My disciples. John 8:32   Then you will know the truth, and the truth will set you free.\u201d John 8:33   \u201cWe are Abraham\u2019s descendants,\u201d they answered. \u201cWe have never been slaves to anyone. How can You say we will be set free?\u201d John 8:34   Jesus replied, \u201cTruly, truly, I tell you, everyone who sins is a slave to sin. John 8:35   A slave does not remain in the house forever, but a son remains forever. John 8:36   So if the Son sets you free, you will be free indeed. John 8:37   I know you are Abraham\u2019s descendants, but you are trying to kill Me because My word has no place within you. John 8:38   I speak of what I have seen in the presence of the Father, and you do what you have heard from your father.\u201d John 8:39   \u201cAbraham is our father,\u201d they replied. \u201cIf you were children of Abraham,\u201d said Jesus, \u201cyou would do the works of Abraham. John 8:40   But now you are trying to kill Me, a man who has told you the truth that I heard from God. Abraham never did such a thing. John 8:41   You are doing the works of your father.\u201d \u201cWe are not illegitimate children,\u201d they declared. \u201cOur only Father is God Himself.\u201d John 8:42   Jesus said to them, \u201cIf God were your Father, you would love Me, for I have come here from God. I have not come on My own, but He sent Me. John 8:43   Why do you not understand what I am saying? It is because you are unable to accept My message. John 8:44   You belong to your father, the devil, and you want to carry out his desires. He was a murderer from the beginning, refusing to uphold the truth, because there is no truth in him. When he lies, he speaks his native language, because he is a liar and the father of lies. John 8:45   But because I speak the truth, you do not believe Me! John 8:46   Which of you can prove Me guilty of sin? If I speak the truth, why do you not believe Me? John 8:47   Whoever belongs to God hears the words of God. The reason you do not hear is that you do not belong to God.\u201d John 8:48   The Jews answered Him, \u201cAre we not right to say that You are a Samaritan and You have a demon?\u201d John 8:49   \u201cI do not have a demon,\u201d Jesus replied, \u201cbut I honor My Father, and you dishonor Me. John 8:50   I do not seek My own glory. There is One who seeks it, and He is the Judge. John 8:51   Truly, truly, I tell you, if anyone keeps My word, he will never see death.\u201d John 8:52   \u201cNow we know that You have a demon!\u201d declared the Jews. \u201cAbraham died, and so did the prophets, yet You say that anyone who keeps Your word will never taste death. John 8:53   Are You greater than our father Abraham? He died, as did the prophets. Who do You claim to be?\u201d John 8:54   Jesus answered, \u201cIf I glorify Myself, My glory means nothing. The One who glorifies Me is My Father, of whom you say, \u2018He is our God.\u2019 John 8:55   You do not know Him, but I know Him. If I said I did not know Him, I would be a liar like you. But I do know Him, and I keep His word. John 8:56   Your father Abraham rejoiced that he would see My day. He saw it and was glad.\u201d John 8:57   Then the Jews said to Him, \u201cYou are not yet fifty years old, and You have seen Abraham?\u201d John 8:58   \u201cTruly, truly, I tell you,\u201d Jesus declared, \u201cbefore Abraham was born, I am!\u201d John 8:59   At this, they picked up stones to throw at Him. But Jesus was hidden and went out of the temple area.</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_08.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_09.html","title":"John 9","text":"<p>John 9:1    Now as Jesus was passing by, He saw a man blind from birth, John 9:2    and His disciples asked Him, \u201cRabbi, who sinned, this man or his parents, that he was born blind?\u201d John 9:3    Jesus answered, \u201cNeither this man nor his parents sinned, but this happened so that the works of God would be displayed in him. John 9:4    While it is daytime, we must do the works of Him who sent Me. Night is coming, when no one can work. John 9:5    While I am in the world, I am the light of the world.\u201d John 9:6    When Jesus had said this, He spit on the ground, made some mud, and applied it to the man\u2019s eyes. John 9:7    Then He told him, \u201cGo, wash in the Pool of Siloam\u201d (which means \u201cSent\u201d). So the man went and washed, and came back seeing. John 9:8    At this, his neighbors and those who had formerly seen him begging began to ask, \u201cIsn\u2019t this the man who used to sit and beg?\u201d John 9:9    Some claimed that he was, but others said, \u201cNo, he just looks like him.\u201d But the man kept saying, \u201cI am the one.\u201d John 9:10   \u201cHow then were your eyes opened?\u201d they asked. John 9:11   He answered, \u201cThe man they call Jesus made some mud and anointed my eyes, and He told me to go to Siloam and wash. So I went and washed and received my sight.\u201d John 9:12   \u201cWhere is He?\u201d they asked. \u201cI do not know,\u201d he answered. John 9:13   They brought to the Pharisees the man who had been blind. John 9:14   Now the day on which Jesus had made the mud and opened his eyes was a Sabbath. John 9:15   So the Pharisees also asked him how he had received his sight. The man answered, \u201cHe put mud on my eyes, and I washed, and now I can see.\u201d John 9:16   Because of this, some of the Pharisees said, \u201cThis man is not from God, for He does not keep the Sabbath.\u201d But others said, \u201cHow can a sinful man perform such signs?\u201d And there was division among them. John 9:17   So once again they asked the man who had been blind, \u201cWhat do you say about Him, since it was your eyes He opened?\u201d \u201cHe is a prophet,\u201d the man replied. John 9:18   The Jews still did not believe that the man had been blind and had received his sight until they summoned his parents John 9:19   and asked, \u201cIs this your son, the one you say was born blind? So how is it that he can now see?\u201d John 9:20   His parents answered, \u201cWe know he is our son, and we know he was born blind. John 9:21   But how he can now see or who opened his eyes, we do not know. Ask him. He is old enough to speak for himself.\u201d John 9:22   His parents said this because they were afraid of the Jews. For the Jews had already determined that anyone who confessed Jesus as the Christ would be put out of the synagogue. John 9:23   That was why his parents said, \u201cHe is old enough. Ask him.\u201d John 9:24   So a second time they called for the man who had been blind and said, \u201cGive glory to God! We know that this man is a sinner.\u201d John 9:25   He answered, \u201cWhether He is a sinner I do not know. There is one thing I do know: I was blind, but now I see!\u201d John 9:26   \u201cWhat did He do to you?\u201d they asked. \u201cHow did He open your eyes?\u201d John 9:27   He replied, \u201cI already told you, and you did not listen. Why do you want to hear it again? Do you also want to become His disciples?\u201d John 9:28   Then they heaped insults on him and said, \u201cYou are His disciple; we are disciples of Moses. John 9:29   We know that God spoke to Moses, but we do not know where this man is from.\u201d John 9:30   \u201cThat is remarkable indeed!\u201d the man said. \u201cYou do not know where He is from, and yet He opened my eyes. John 9:31   We know that God does not listen to sinners, but He does listen to the one who worships Him and does His will. John 9:32   Never before has anyone heard of opening the eyes of a man born blind. John 9:33   If this man were not from God, He could do no such thing.\u201d John 9:34   They replied, \u201cYou were born in utter sin, and you are instructing us?\u201d And they threw him out. John 9:35   When Jesus heard that they had thrown him out, He found the man and said, \u201cDo you believe in the Son of Man?\u201d John 9:36   \u201cWho is He, Sir?\u201d he replied. \u201cTell me so that I may believe in Him.\u201d John 9:37   \u201cYou have already seen Him,\u201d Jesus answered. \u201cHe is the One speaking with you.\u201d John 9:38   \u201cLord, I believe,\u201d he said. And he worshiped Jesus. John 9:39   Then Jesus declared, \u201cFor judgment I have come into this world, so that the blind may see and those who see may become blind.\u201d John 9:40   Some of the Pharisees who were with Him heard this, and they asked Him, \u201cAre we blind too?\u201d John 9:41   \u201cIf you were blind,\u201d Jesus replied, \u201cyou would not be guilty of sin. But since you claim you can see, your guilt remains.\u201d</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_09.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_10.html","title":"John 10","text":"<p>John 10:1   \u201cTruly, truly, I tell you, whoever does not enter the sheepfold by the gate, but climbs in some other way, is a thief and a robber. John 10:2   But the one who enters by the gate is the shepherd of the sheep. John 10:3   The gatekeeper opens the gate for him, and the sheep listen for his voice. He calls his own sheep by name and leads them out. John 10:4   When he has brought out all his own, he goes on ahead of them, and his sheep follow him because they know his voice. John 10:5   But they will never follow a stranger; in fact, they will flee from him because they do not recognize his voice.\u201d John 10:6   Jesus spoke to them using this illustration, but they did not understand what He was telling them. John 10:7   So He said to them again, \u201cTruly, truly, I tell you, I am the gate for the sheep. John 10:8   All who came before Me were thieves and robbers, but the sheep did not listen to them. John 10:9   I am the gate. If anyone enters through Me, he will be saved. He will come in and go out and find pasture. John 10:10  The thief comes only to steal and kill and destroy. I have come that they may have life, and have it in all its fullness. John 10:11  I am the good shepherd. The good shepherd lays down His life for the sheep. John 10:12  The hired hand is not the shepherd, and the sheep are not his own. When he sees the wolf coming, he abandons the sheep and runs away. Then the wolf pounces on them and scatters the flock. John 10:13  The man runs away because he is a hired servant and is unconcerned for the sheep. John 10:14  I am the good shepherd. I know My sheep and My sheep know Me, John 10:15  just as the Father knows Me and I know the Father. And I lay down My life for the sheep. John 10:16  I have other sheep that are not of this fold. I must bring them in as well, and they will listen to My voice. Then there will be one flock and one shepherd. John 10:17  The reason the Father loves Me is that I lay down My life in order to take it up again. John 10:18  No one takes it from Me, but I lay it down of My own accord. I have authority to lay it down and authority to take it up again. This charge I have received from My Father.\u201d John 10:19  Again there was division among the Jews because of Jesus\u2019 message. John 10:20  Many of them said, \u201cHe is demon-possessed and insane. Why would you listen to Him?\u201d John 10:21  But others replied, \u201cThese are not the words of a man possessed by a demon. Can a demon open the eyes of the blind?\u201d John 10:22  At that time the Feast of Dedication took place in Jerusalem. It was winter, John 10:23  and Jesus was walking in the temple courts in Solomon\u2019s Colonnade. John 10:24  So the Jews gathered around Him and demanded, \u201cHow long will You keep us in suspense? If You are the Christ, tell us plainly.\u201d John 10:25  \u201cI already told you,\u201d Jesus replied, \u201cbut you did not believe. The works I do in My Father\u2019s name testify on My behalf. John 10:26  But because you are not My sheep, you refuse to believe. John 10:27  My sheep listen to My voice; I know them, and they follow Me. John 10:28  I give them eternal life, and they will never perish. No one can snatch them out of My hand. John 10:29  My Father who has given them to Me is greater than all. No one can snatch them out of My Father\u2019s hand. John 10:30  I and the Father are one.\u201d John 10:31  At this, the Jews again picked up stones to stone Him. John 10:32  But Jesus responded, \u201cI have shown you many good works from the Father. For which of these do you stone Me?\u201d John 10:33  \u201cWe are not stoning You for any good work,\u201d said the Jews, \u201cbut for blasphemy, because You, who are a man, make Yourself out to be God.\u201d John 10:34  Jesus replied, \u201cIs it not written in your Law: \u2018I have said you are gods\u2019? John 10:35  If he called them gods to whom the word of God came\u2014and the Scripture cannot be broken\u2014 John 10:36  then what about the One whom the Father sanctified and sent into the world? How then can you accuse Me of blasphemy for stating that I am the Son of God? John 10:37  If I am not doing the works of My Father, then do not believe Me. John 10:38  But if I am doing them, even though you do not believe Me, believe the works themselves, so that you may know and understand that the Father is in Me, and I am in the Father.\u201d John 10:39  At this, they tried again to seize Him, but He escaped their grasp. John 10:40  Then Jesus went back across the Jordan to the place where John had first been baptizing, and He stayed there. John 10:41  Many came to Him and said, \u201cAlthough John never performed a sign, everything he said about this man was true.\u201d John 10:42  And many in that place believed in Jesus.</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_10.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_11.html","title":"John 11","text":"<p>John 11:1   At this time a man named Lazarus was sick. He lived in Bethany, the village of Mary and her sister Martha. John 11:2   (Mary, whose brother Lazarus was sick, was to anoint the Lord with perfume and wipe His feet with her hair.) John 11:3   So the sisters sent word to Jesus, \u201cLord, the one You love is sick.\u201d John 11:4   When Jesus heard this, He said, \u201cThis sickness will not end in death. No, it is for the glory of God, so that the Son of God may be glorified through it.\u201d John 11:5   Now Jesus loved Martha and her sister and Lazarus. John 11:6   So on hearing that Lazarus was sick, He stayed where He was for two days, John 11:7   and then He said to the disciples, \u201cLet us go back to Judea.\u201d John 11:8   \u201cRabbi,\u201d they replied, \u201cthe Jews just tried to stone You, and You are going back there?\u201d John 11:9   Jesus answered, \u201cAre there not twelve hours of daylight? If anyone walks in the daytime, he will not stumble, because he sees by the light of this world. John 11:10  But if anyone walks at night, he will stumble, because he has no light.\u201d John 11:11  After He had said this, He told them, \u201cOur friend Lazarus has fallen asleep, but I am going there to wake him up.\u201d John 11:12  His disciples replied, \u201cLord, if he is sleeping, he will get better.\u201d John 11:13  They thought that Jesus was talking about actual sleep, but He was speaking about the death of Lazarus. John 11:14  So Jesus told them plainly, \u201cLazarus is dead, John 11:15  and for your sake I am glad I was not there, so that you may believe. But let us go to him.\u201d John 11:16  Then Thomas called Didymus said to his fellow disciples, \u201cLet us also go, so that we may die with Him.\u201d John 11:17  When Jesus arrived, He found that Lazarus had already spent four days in the tomb. John 11:18  Now Bethany was near Jerusalem, a little less than two miles away, John 11:19  and many of the Jews had come to Martha and Mary to console them in the loss of their brother. John 11:20  So when Martha heard that Jesus was coming, she went out to meet Him, but Mary stayed at home. John 11:21  Martha said to Jesus, \u201cLord, if You had been here, my brother would not have died. John 11:22  But even now I know that God will give You whatever You ask of Him.\u201d John 11:23  \u201cYour brother will rise again,\u201d Jesus told her. John 11:24  Martha replied, \u201cI know that he will rise again in the resurrection at the last day.\u201d John 11:25  Jesus said to her, \u201cI am the resurrection and the life. Whoever believes in Me will live, even though he dies. John 11:26  And everyone who lives and believes in Me will never die. Do you believe this?\u201d John 11:27  \u201cYes, Lord,\u201d she answered, \u201cI believe that You are the Christ, the Son of God, who was to come into the world.\u201d John 11:28  After Martha had said this, she went back and called her sister Mary aside to tell her, \u201cThe Teacher is here and is asking for you.\u201d John 11:29  And when Mary heard this, she got up quickly and went to Him. John 11:30  Now Jesus had not yet entered the village, but was still at the place where Martha had met Him. John 11:31  When the Jews who were in the house consoling Mary saw how quickly she got up and went out, they followed her, supposing she was going to the tomb to mourn there. John 11:32  When Mary came to Jesus and saw Him, she fell at His feet and said, \u201cLord, if You had been here, my brother would not have died.\u201d John 11:33  When Jesus saw her weeping, and the Jews who had come with her also weeping, He was deeply moved in spirit and troubled. John 11:34  \u201cWhere have you put him?\u201d He asked. \u201cCome and see, Lord,\u201d they answered. John 11:35  Jesus wept. John 11:36  Then the Jews said, \u201cSee how He loved him!\u201d John 11:37  But some of them asked, \u201cCould not this man who opened the eyes of the blind also have kept Lazarus from dying?\u201d John 11:38  Jesus, once again deeply moved, came to the tomb. It was a cave with a stone laid across the entrance. John 11:39  \u201cTake away the stone,\u201d Jesus said. \u201cLord, by now he stinks,\u201d said Martha, the sister of the dead man. \u201cIt has already been four days.\u201d John 11:40  Jesus replied, \u201cDid I not tell you that if you believed, you would see the glory of God?\u201d John 11:41  So they took away the stone. Then Jesus lifted His eyes upward and said, \u201cFather, I thank You that You have heard Me. John 11:42  I knew that You always hear Me, but I say this for the benefit of the people standing here, so they may believe that You sent Me.\u201d John 11:43  After Jesus had said this, He called out in a loud voice, \u201cLazarus, come out!\u201d John 11:44  The man who had been dead came out with his hands and feet bound in strips of linen, and his face wrapped in a cloth. \u201cUnwrap him and let him go,\u201d Jesus told them. John 11:45  Therefore many of the Jews who had come to Mary, and had seen what Jesus did, believed in Him. John 11:46  But some of them went to the Pharisees and told them what Jesus had done. John 11:47  Then the chief priests and Pharisees convened the Sanhedrin and said, \u201cWhat are we to do? This man is performing many signs. John 11:48  If we let Him go on like this, everyone will believe in Him, and then the Romans will come and take away both our place and our nation.\u201d John 11:49  But one of them, named Caiaphas, who was high priest that year, said to them, \u201cYou know nothing at all! John 11:50  You do not realize that it is better for you that one man die for the people than that the whole nation perish.\u201d John 11:51  Caiaphas did not say this on his own. Instead, as high priest that year, he was prophesying that Jesus would die for the nation, John 11:52  and not only for the nation, but also for the scattered children of God, to gather them together into one. John 11:53  So from that day on they plotted to kill Him. John 11:54  As a result, Jesus no longer went about publicly among the Jews, but He withdrew to a town called Ephraim in an area near the wilderness. And He stayed there with the disciples. John 11:55  Now the Jewish Passover was near, and many people went up from the country to Jerusalem to purify themselves before the Passover. John 11:56  They kept looking for Jesus and asking one another as they stood in the temple courts, \u201cWhat do you think? Will He come to the feast at all?\u201d John 11:57  But the chief priests and Pharisees had given orders that anyone who knew where He was must report it, so that they could arrest Him.</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_11.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_12.html","title":"John 12","text":"<p>John 12:1   Six days before the Passover, Jesus came to Bethany, the hometown of Lazarus, whom He had raised from the dead. John 12:2   So they hosted a dinner for Jesus there. Martha served, and Lazarus was among those reclining at the table with Him. John 12:3   Then Mary took about a pint of expensive perfume, made of pure nard, and she anointed Jesus\u2019 feet and wiped them with her hair. And the house was filled with the fragrance of the perfume. John 12:4   But one of His disciples, Judas Iscariot, who was going to betray Him, asked, John 12:5   \u201cWhy wasn\u2019t this perfume sold for three hundred denarii and the money given to the poor?\u201d John 12:6   Judas did not say this because he cared about the poor, but because he was a thief. As keeper of the money bag, he used to take from what was put into it. John 12:7   \u201cLeave her alone,\u201d Jesus replied. \u201cShe has kept this perfume in preparation for the day of My burial. John 12:8   The poor you will always have with you, but you will not always have Me.\u201d John 12:9   Meanwhile a large crowd of Jews learned that Jesus was there. And they came not only because of Him, but also to see Lazarus, whom He had raised from the dead. John 12:10  So the chief priests made plans to kill Lazarus as well, John 12:11  for on account of him many of the Jews were deserting them and believing in Jesus. John 12:12  The next day the great crowd that had come to the feast heard that Jesus was coming to Jerusalem. John 12:13  They took palm branches and went out to meet Him, shouting: \u201cHosanna!\u201d \u201cBlessed is He who comes in the name of the Lord!\u201d \u201cBlessed is the King of Israel!\u201d John 12:14  Finding a young donkey, Jesus sat on it, as it is written: John 12:15  \u201cDo not be afraid, O Daughter of Zion. See, your King is coming, seated on the colt of a donkey.\u201d John 12:16  At first His disciples did not understand these things, but after Jesus was glorified they remembered what had been done to Him, and they realized that these very things had also been written about Him. John 12:17  Meanwhile, many people who had been with Jesus when He called Lazarus from the tomb and raised him from the dead continued to testify. John 12:18  That is also why the crowd went out to meet Him, because they heard that He had performed this sign. John 12:19  Then the Pharisees said to one another, \u201cYou can see that this is doing you no good. Look how the whole world has gone after Him!\u201d John 12:20  Now there were some Greeks among those who went up to worship at the feast. John 12:21  They came to Philip, who was from Bethsaida in Galilee, and requested of him, \u201cSir, we want to see Jesus.\u201d John 12:22  Philip relayed this appeal to Andrew, and both of them went and told Jesus. John 12:23  But Jesus replied, \u201cThe hour has come for the Son of Man to be glorified. John 12:24  Truly, truly, I tell you, unless a kernel of wheat falls to the ground and dies, it remains only a seed. But if it dies, it bears much fruit. John 12:25  Whoever loves his life will lose it, but whoever hates his life in this world will keep it for eternal life. John 12:26  If anyone serves Me, he must follow Me; and where I am, My servant will be as well. If anyone serves Me, the Father will honor him. John 12:27  Now My soul is troubled, and what shall I say? \u2018Father, save Me from this hour\u2019? No, it is for this purpose that I have come to this hour. John 12:28  Father, glorify Your name!\u201d Then a voice came from heaven: \u201cI have glorified it, and I will glorify it again.\u201d John 12:29  The crowd standing there heard it and said that it had thundered. Others said that an angel had spoken to Him. John 12:30  In response, Jesus said, \u201cThis voice was not for My benefit, but yours. John 12:31  Now judgment is upon this world; now the prince of this world will be cast out. John 12:32  And I, when I am lifted up from the earth, will draw everyone to Myself.\u201d John 12:33  He said this to indicate the kind of death He was going to die. John 12:34  The crowd replied, \u201cWe have heard from the Law that the Christ will remain forever. So how can You say that the Son of Man must be lifted up? Who is this Son of Man?\u201d John 12:35  Then Jesus told them, \u201cFor a little while longer, the Light will be among you. Walk while you have the Light, so that darkness will not overtake you. The one who walks in the darkness does not know where he is going. John 12:36  While you have the Light, believe in the Light, so that you may become sons of light.\u201d After Jesus had spoken these things, He went away and was hidden from them. John 12:37  Although Jesus had performed so many signs in their presence, they still did not believe in Him. John 12:38  This was to fulfill the word of Isaiah the prophet: \u201cLord, who has believed our message? And to whom has the arm of the Lord been revealed?\u201d John 12:39  For this reason they were unable to believe. For again, Isaiah says: John 12:40  \u201cHe has blinded their eyes and hardened their hearts, so that they cannot see with their eyes, and understand with their hearts, and turn, and I would heal them.\u201d John 12:41  Isaiah said these things because he saw Jesus\u2019 glory and spoke about Him. John 12:42  Nevertheless, many of the leaders believed in Him. But because of the Pharisees they did not confess Him, for fear that they would be put out of the synagogue. John 12:43  For they loved praise from men more than praise from God. John 12:44  Then Jesus cried out, \u201cWhoever believes in Me does not believe in Me alone, but in the One who sent Me. John 12:45  And whoever sees Me sees the One who sent Me. John 12:46  I have come into the world as a light, so that no one who believes in Me should remain in darkness. John 12:47  As for anyone who hears My words and does not keep them, I do not judge him. For I have not come to judge the world, but to save the world. John 12:48  There is a judge for the one who rejects Me and does not receive My words: The word that I have spoken will judge him on the last day. John 12:49  I have not spoken on My own, but the Father who sent Me has commanded Me what to say and how to say it. John 12:50  And I know that His command leads to eternal life. So I speak exactly what the Father has told Me to say.\u201d</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_12.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_13.html","title":"John 13","text":"<p>John 13:1   It was now just before the Passover Feast, and Jesus knew that His hour had come to leave this world and return to the Father. Having loved His own who were in the world, He loved them to the very end. John 13:2   The evening meal was underway, and the devil had already put into the heart of Judas, the son of Simon Iscariot, to betray Jesus. John 13:3   Jesus knew that the Father had delivered all things into His hands, and that He had come from God and was returning to God. John 13:4   So He got up from the supper, laid aside His outer garments, and wrapped a towel around His waist. John 13:5   After that, He poured water into a basin and began to wash the disciples\u2019 feet and dry them with the towel that was around Him. John 13:6   He came to Simon Peter, who asked Him, \u201cLord, are You going to wash my feet?\u201d John 13:7   Jesus replied, \u201cYou do not realize now what I am doing, but later you will understand.\u201d John 13:8   \u201cNever shall You wash my feet!\u201d Peter told Him. Jesus answered, \u201cUnless I wash you, you have no part with Me.\u201d John 13:9   \u201cThen, Lord,\u201d Simon Peter replied, \u201cnot only my feet, but my hands and my head as well!\u201d John 13:10  Jesus told him, \u201cWhoever has already bathed needs only to wash his feet, and he will be completely clean. And you are clean, though not all of you.\u201d John 13:11  For He knew who would betray Him. That is why He said, \u201cNot all of you are clean.\u201d John 13:12  When Jesus had washed their feet and put on His outer garments, He reclined with them again and asked, \u201cDo you know what I have done for you? John 13:13  You call Me Teacher and Lord, and rightly so, because I am. John 13:14  So if I, your Lord and Teacher, have washed your feet, you also should wash one another\u2019s feet. John 13:15  I have set you an example so that you should do as I have done for you. John 13:16  Truly, truly, I tell you, no servant is greater than his master, nor is a messenger greater than the one who sent him. John 13:17  If you know these things, you will be blessed if you do them. John 13:18  I am not speaking about all of you; I know whom I have chosen. But this is to fulfill the Scripture: \u2018The one who shares My bread has lifted up his heel against Me.\u2019 John 13:19  I am telling you now before it happens, so that when it comes to pass, you will believe that I am He. John 13:20  Truly, truly, I tell you, whoever receives the one I send receives Me, and whoever receives Me receives the One who sent Me.\u201d John 13:21  After Jesus had said this, He became troubled in spirit and testified, \u201cTruly, truly, I tell you, one of you will betray Me.\u201d John 13:22  The disciples looked at one another, perplexed as to which of them He meant. John 13:23  One of His disciples, the one whom Jesus loved, was reclining at His side. John 13:24  So Simon Peter motioned to him to ask Jesus which one He was talking about. John 13:25  Leaning back against Jesus, he asked, \u201cLord, who is it?\u201d John 13:26  Jesus answered, \u201cIt is the one to whom I give this morsel after I have dipped it.\u201d Then He dipped the morsel and gave it to Judas son of Simon Iscariot. John 13:27  And when Judas had taken the morsel, Satan entered into him. Then Jesus said to Judas, \u201cWhat you are about to do, do quickly.\u201d John 13:28  But no one at the table knew why Jesus had said this to him. John 13:29  Since Judas kept the money bag, some thought that Jesus was telling him to buy what was needed for the feast, or to give something to the poor. John 13:30  As soon as he had received the morsel, Judas went out into the night. John 13:31  When Judas had gone out, Jesus said, \u201cNow the Son of Man is glorified, and God is glorified in Him. John 13:32  If God is glorified in Him, God will also glorify the Son in Himself\u2014and will glorify Him at once. John 13:33  Little children, I am with you only a little while longer. You will look for Me, and as I said to the Jews, so now I say to you: \u2018Where I am going, you cannot come.\u2019 John 13:34  A new commandment I give you: Love one another. As I have loved you, so you also must love one another. John 13:35  By this everyone will know that you are My disciples, if you love one another.\u201d John 13:36  \u201cLord, where are You going?\u201d Simon Peter asked. Jesus answered, \u201cWhere I am going, you cannot follow Me now, but you will follow later.\u201d John 13:37  \u201cLord,\u201d said Peter, \u201cwhy can\u2019t I follow You now? I will lay down my life for You.\u201d John 13:38  \u201cWill you lay down your life for Me?\u201d Jesus replied. \u201cTruly, truly, I tell you, before the rooster crows, you will deny Me three times.</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_13.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_14.html","title":"John 14","text":"<p>John 14:1   \u201cDo not let your hearts be troubled. You believe in God; believe in Me as well. John 14:2   In My Father\u2019s house are many rooms. If it were not so, would I have told you that I am going there to prepare a place for you? John 14:3   And if I go and prepare a place for you, I will come back and welcome you into My presence, so that you also may be where I am. John 14:4   You know the way to the place where I am going.\u201d John 14:5   \u201cLord,\u201d said Thomas, \u201cwe do not know where You are going, so how can we know the way?\u201d John 14:6   Jesus answered, \u201cI am the way and the truth and the life. No one comes to the Father except through Me. John 14:7   If you had known Me, you would know My Father as well. From now on you do know Him and have seen Him.\u201d John 14:8   Philip said to Him, \u201cLord, show us the Father, and that will be enough for us.\u201d John 14:9   Jesus replied, \u201cPhilip, I have been with you all this time, and still you do not know Me? Anyone who has seen Me has seen the Father. How can you say, \u2018Show us the Father\u2019? John 14:10  Do you not believe that I am in the Father and the Father is in Me? The words I say to you, I do not speak on My own. Instead, it is the Father dwelling in Me, performing His works. John 14:11  Believe Me that I am in the Father and the Father is in Me\u2014or at least believe on account of the works themselves. John 14:12  Truly, truly, I tell you, whoever believes in Me will also do the works that I am doing. He will do even greater things than these, because I am going to the Father. John 14:13  And I will do whatever you ask in My name, so that the Father may be glorified in the Son. John 14:14  If you ask Me for anything in My name, I will do it. John 14:15  If you love Me, you will keep My commandments. John 14:16  And I will ask the Father, and He will give you another Advocate to be with you forever\u2014 John 14:17  the Spirit of truth. The world cannot receive Him, because it neither sees Him nor knows Him. But you do know Him, for He abides with you and will be in you. John 14:18  I will not leave you as orphans; I will come to you. John 14:19  In a little while the world will see Me no more, but you will see Me. Because I live, you also will live. John 14:20  On that day you will know that I am in My Father, and you are in Me, and I am in you. John 14:21  Whoever has My commandments and keeps them is the one who loves Me. The one who loves Me will be loved by My Father, and I will love him and reveal Myself to him.\u201d John 14:22  Judas (not Iscariot) asked Him, \u201cLord, why are You going to reveal Yourself to us and not to the world?\u201d John 14:23  Jesus replied, \u201cIf anyone loves Me, he will keep My word. My Father will love him, and We will come to him and make Our home with him. John 14:24  Whoever does not love Me does not keep My words. The word that you hear is not My own, but it is from the Father who sent Me. John 14:25  All this I have spoken to you while I am still with you. John 14:26  But the Advocate, the Holy Spirit, whom the Father will send in My name, will teach you all things and will remind you of everything I have told you. John 14:27  Peace I leave with you; My peace I give to you. I do not give to you as the world gives. Do not let your hearts be troubled; do not be afraid. John 14:28  You heard Me say, \u2018I am going away, and I am coming back to you.\u2019 If you loved Me, you would rejoice that I am going to the Father, because the Father is greater than I. John 14:29  And now I have told you before it happens, so that when it does happen, you will believe. John 14:30  I will not speak with you much longer, for the prince of this world is coming, and he has no claim on Me. John 14:31  But I do exactly what the Father has commanded Me, so that the world may know that I love the Father. Get up! Let us go on from here.</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_14.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_15.html","title":"John 15","text":"<p>John 15:1   \u201cI am the true vine, and My Father is the keeper of the vineyard. John 15:2   He cuts off every branch in Me that bears no fruit, and every branch that does bear fruit, He prunes to make it even more fruitful. John 15:3   You are already clean because of the word I have spoken to you. John 15:4   Remain in Me, and I will remain in you. Just as no branch can bear fruit by itself unless it remains in the vine, neither can you bear fruit unless you remain in Me. John 15:5   I am the vine and you are the branches. The one who remains in Me, and I in him, will bear much fruit. For apart from Me you can do nothing. John 15:6   If anyone does not remain in Me, he is like a branch that is thrown away and withers. Such branches are gathered up, thrown into the fire, and burned. John 15:7   If you remain in Me and My words remain in you, ask whatever you wish, and it will be done for you. John 15:8   This is to My Father\u2019s glory, that you bear much fruit, proving yourselves to be My disciples. John 15:9   As the Father has loved Me, so have I loved you. Remain in My love. John 15:10  If you keep My commandments, you will remain in My love, just as I have kept My Father\u2019s commandments and remain in His love. John 15:11  I have told you these things so that My joy may be in you and your joy may be complete. John 15:12  This is My commandment, that you love one another as I have loved you. John 15:13  Greater love has no one than this, that he lay down his life for his friends. John 15:14  You are My friends if you do what I command you. John 15:15  No longer do I call you servants, for a servant does not understand what his master is doing. But I have called you friends, because everything I have learned from My Father I have made known to you. John 15:16  You did not choose Me, but I chose you. And I appointed you to go and bear fruit\u2014fruit that will remain\u2014so that whatever you ask the Father in My name, He will give you. John 15:17  This is My command to you: Love one another. John 15:18  If the world hates you, understand that it hated Me first. John 15:19  If you were of the world, it would love you as its own. Instead, the world hates you, because you are not of the world, but I have chosen you out of the world. John 15:20  Remember the word that I spoke to you: \u2018No servant is greater than his master.\u2019 If they persecuted Me, they will persecute you as well; if they kept My word, they will keep yours as well. John 15:21  But they will treat you like this because of My name, since they do not know the One who sent Me. John 15:22  If I had not come and spoken to them, they would not be guilty of sin. Now, however, they have no excuse for their sin. John 15:23  Whoever hates Me hates My Father as well. John 15:24  If I had not done among them the works that no one else did, they would not be guilty of sin; but now they have seen and hated both Me and My Father. John 15:25  But this is to fulfill what is written in their Law: \u2018They hated Me without reason.\u2019 John 15:26  When the Advocate comes, whom I will send to you from the Father\u2014the Spirit of truth who proceeds from the Father\u2014He will testify about Me. John 15:27  And you also must testify, because you have been with Me from the beginning.</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_15.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_16.html","title":"John 16","text":"<p>John 16:1   \u201cI have told you these things so that you will not fall away. John 16:2   They will put you out of the synagogues. In fact, a time is coming when anyone who kills you will think he is offering a service to God. John 16:3   They will do these things because they have not known the Father or Me. John 16:4   But I have told you these things so that when their hour comes, you will remember that I told you about them. I did not tell you these things from the beginning, because I was with you. John 16:5   Now, however, I am going to Him who sent Me; yet none of you asks Me, \u2018Where are You going?\u2019 John 16:6   Instead, your hearts are filled with sorrow because I have told you these things. John 16:7   But I tell you the truth, it is for your benefit that I am going away. Unless I go away, the Advocate will not come to you; but if I go, I will send Him to you. John 16:8   And when He comes, He will convict the world in regard to sin and righteousness and judgment: John 16:9   in regard to sin, because they do not believe in Me; John 16:10  in regard to righteousness, because I am going to the Father and you will no longer see Me; John 16:11  and in regard to judgment, because the prince of this world has been condemned. John 16:12  I still have much to tell you, but you cannot yet bear to hear it. John 16:13  However, when the Spirit of truth comes, He will guide you into all truth. For He will not speak on His own, but He will speak what He hears, and He will declare to you what is to come. John 16:14  He will glorify Me by taking from what is Mine and disclosing it to you. John 16:15  Everything that belongs to the Father is Mine. That is why I said that the Spirit will take from what is Mine and disclose it to you. John 16:16  In a little while you will see Me no more, and then after a little while you will see Me.\u201d John 16:17  Then some of His disciples asked one another, \u201cWhy is He telling us, \u2018In a little while you will not see Me, and then after a little while you will see Me\u2019 and \u2018Because I am going to the Father\u2019?\u201d John 16:18  They kept asking, \u201cWhy is He saying, \u2018a little while\u2019? We do not understand what He is saying.\u201d John 16:19  Aware that they wanted to question Him, Jesus said to them, \u201cAre you asking one another why I said, \u2018In a little while you will not see Me, and then after a little while you will see Me\u2019? John 16:20  Truly, truly, I tell you, you will weep and wail while the world rejoices. You will grieve, but your grief will turn to joy. John 16:21  A woman has pain in childbirth because her time has come; but when she brings forth her child, she forgets her anguish because of her joy that a child has been born into the world. John 16:22  So also you have sorrow now, but I will see you again and your hearts will rejoice, and no one will take away your joy. John 16:23  In that day you will no longer ask Me anything. Truly, truly, I tell you, whatever you ask the Father in My name, He will give you. John 16:24  Until now you have not asked for anything in My name. Ask and you will receive, so that your joy may be complete. John 16:25  I have spoken these things to you in figures of speech. An hour is coming when I will no longer speak to you this way, but will tell you plainly about the Father. John 16:26  In that day you will ask in My name. I am not saying that I will ask the Father on your behalf. John 16:27  For the Father Himself loves you, because you have loved Me and have believed that I came from God. John 16:28  I came from the Father and entered the world. In turn, I will leave the world and go to the Father.\u201d John 16:29  His disciples said, \u201cSee, now You are speaking plainly and without figures of speech. John 16:30  Now we understand that You know all things and that You have no need for anyone to question You. Because of this, we believe that You came from God.\u201d John 16:31  \u201cDo you finally believe?\u201d Jesus replied. John 16:32  \u201cLook, an hour is coming and has already come when you will be scattered, each to his own home, and you will leave Me all alone. Yet I am not alone, because the Father is with Me. John 16:33  I have told you these things so that in Me you may have peace. In the world you will have tribulation. But take courage; I have overcome the world!\u201d</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_16.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_17.html","title":"John 17","text":"<p>John 17:1   When Jesus had spoken these things, He lifted up His eyes to heaven and said, \u201cFather, the hour has come. Glorify Your Son, that Your Son may glorify You. John 17:2   For You granted Him authority over all people, so that He may give eternal life to all those You have given Him. John 17:3   Now this is eternal life, that they may know You, the only true God, and Jesus Christ, whom You have sent. John 17:4   I have glorified You on earth by accomplishing the work You gave Me to do. John 17:5   And now, Father, glorify Me in Your presence with the glory I had with You before the world existed. John 17:6   I have revealed Your name to those You have given Me out of the world. They were Yours; You gave them to Me, and they have kept Your word. John 17:7   Now they know that everything You have given Me comes from You. John 17:8   For I have given them the words You gave Me, and they have received them. They knew with certainty that I came from You, and they believed that You sent Me. John 17:9   I ask on their behalf. I do not ask on behalf of the world, but on behalf of those You have given Me; for they are Yours. John 17:10  All I have is Yours, and all You have is Mine; and in them I have been glorified. John 17:11  I will no longer be in the world, but they are in the world, and I am coming to You. Holy Father, protect them by Your name, the name You gave Me, so that they may be one as We are one. John 17:12  While I was with them, I protected and preserved them by Your name, the name You gave Me. Not one of them has been lost, except the son of destruction, so that the Scripture would be fulfilled. John 17:13  But now I am coming to You; and I am saying these things while I am in the world, so that they may have My joy fulfilled within them. John 17:14  I have given them Your word and the world has hated them. For they are not of the world, just as I am not of the world. John 17:15  I am not asking that You take them out of the world, but that You keep them from the evil one. John 17:16  They are not of the world, just as I am not of the world. John 17:17  Sanctify them by the truth; Your word is truth. John 17:18  As You sent Me into the world, I have also sent them into the world. John 17:19  For them I sanctify Myself, so that they too may be sanctified by the truth. John 17:20  I am not asking on behalf of them alone, but also on behalf of those who will believe in Me through their message, John 17:21  that all of them may be one, as You, Father, are in Me, and I am in You. May they also be in Us, so that the world may believe that You sent Me. John 17:22  I have given them the glory You gave Me, so that they may be one as We are one\u2014 John 17:23  I in them and You in Me\u2014that they may be perfectly united, so that the world may know that You sent Me and have loved them just as You have loved Me. John 17:24  Father, I want those You have given Me to be with Me where I am, that they may see the glory You gave Me because You loved Me before the foundation of the world. John 17:25  Righteous Father, although the world has not known You, I know You, and they know that You sent Me. John 17:26  And I have made Your name known to them and will continue to make it known, so that the love You have for Me may be in them, and I in them.\u201d</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_17.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_18.html","title":"John 18","text":"<p>John 18:1   After Jesus had spoken these words, He went out with His disciples across the Kidron Valley, where they entered a garden. John 18:2   Now Judas His betrayer also knew the place, because Jesus had often met there with His disciples. John 18:3   So Judas brought a band of soldiers and officers from the chief priests and Pharisees. They arrived at the garden carrying lanterns, torches, and weapons. John 18:4   Jesus, knowing all that was coming upon Him, stepped forward and asked them, \u201cWhom are you seeking?\u201d John 18:5   \u201cJesus of Nazareth,\u201d they answered. Jesus said, \u201cI am He.\u201d And Judas His betrayer was standing there with them. John 18:6   When Jesus said, \u201cI am He,\u201d they drew back and fell to the ground. John 18:7   So He asked them again, \u201cWhom are you seeking?\u201d \u201cJesus of Nazareth,\u201d they answered. John 18:8   \u201cI told you that I am He,\u201d Jesus replied. \u201cSo if you are looking for Me, let these men go.\u201d John 18:9   This was to fulfill the word He had spoken: \u201cI have not lost one of those You have given Me.\u201d John 18:10  Then Simon Peter drew his sword and struck the servant of the high priest, cutting off his right ear. The servant\u2019s name was Malchus. John 18:11  \u201cPut your sword back in its sheath!\u201d Jesus said to Peter. \u201cShall I not drink the cup the Father has given Me?\u201d John 18:12  Then the band of soldiers, with its commander and the officers of the Jews, arrested Jesus and bound Him. John 18:13  They brought Him first to Annas, who was the father-in-law of Caiaphas, the high priest that year. John 18:14  Caiaphas was the one who had advised the Jews that it would be better if one man died for the people. John 18:15  Now Simon Peter and another disciple were following Jesus. Since that disciple was known to the high priest, he also went with Jesus into the courtyard of the high priest. John 18:16  But Peter stood outside at the door. Then the disciple who was known to the high priest went out and spoke to the doorkeeper, and brought Peter in. John 18:17  At this, the servant girl watching the door said to Peter, \u201cAren\u2019t you also one of this man\u2019s disciples?\u201d \u201cI am not,\u201d he answered. John 18:18  Because it was cold, the servants and officers were standing around a charcoal fire they had made to keep warm. And Peter was also standing with them, warming himself. John 18:19  Meanwhile, the high priest questioned Jesus about His disciples and His teaching. John 18:20  \u201cI have spoken openly to the world,\u201d Jesus answered. \u201cI always taught in the synagogues and at the temple, where all the Jews come together. I said nothing in secret. John 18:21  Why are you asking Me? Ask those who heard My message. Surely they know what I said.\u201d John 18:22  When Jesus had said this, one of the officers standing nearby slapped Him in the face and said, \u201cIs this how You answer the high priest?\u201d John 18:23  Jesus replied, \u201cIf I said something wrong, testify as to what was wrong. But if I spoke correctly, why did you strike Me?\u201d John 18:24  Then Annas sent Him, still bound, to Caiaphas the high priest. John 18:25  Simon Peter was still standing and warming himself. So they asked him, \u201cAren\u2019t you also one of His disciples?\u201d He denied it and said, \u201cI am not.\u201d John 18:26  One of the high priest\u2019s servants, a relative of the man whose ear Peter had cut off, asked, \u201cDidn\u2019t I see you with Him in the garden?\u201d John 18:27  Peter denied it once more, and immediately a rooster crowed. John 18:28  Then they led Jesus away from Caiaphas into the Praetorium. By now it was early morning, and the Jews did not enter the Praetorium, to avoid being defiled and unable to eat the Passover. John 18:29  So Pilate went out to them and asked, \u201cWhat accusation are you bringing against this man?\u201d John 18:30  \u201cIf He were not a criminal,\u201d they replied, \u201cwe would not have handed Him over to you.\u201d John 18:31  \u201cYou take Him and judge Him by your own law,\u201d Pilate told them. \u201cWe are not permitted to execute anyone,\u201d the Jews replied. John 18:32  This was to fulfill the word that Jesus had spoken to indicate the kind of death He was going to die. John 18:33  Pilate went back into the Praetorium, summoned Jesus, and asked Him, \u201cAre You the King of the Jews?\u201d John 18:34  \u201cAre you saying this on your own,\u201d Jesus asked, \u201cor did others tell you about Me?\u201d John 18:35  \u201cAm I a Jew?\u201d Pilate replied. \u201cYour own people and chief priests handed You over to me. What have You done?\u201d John 18:36  Jesus answered, \u201cMy kingdom is not of this world; if it were, My servants would fight to prevent My arrest by the Jews. But now My kingdom is not of this realm.\u201d John 18:37  \u201cThen You are a king!\u201d Pilate said. \u201cYou say that I am a king,\u201d Jesus answered. \u201cFor this reason I was born and have come into the world, to testify to the truth. Everyone who belongs to the truth listens to My voice.\u201d John 18:38  \u201cWhat is truth?\u201d Pilate asked. And having said this, he went out again to the Jews and told them, \u201cI find no basis for a charge against Him. John 18:39  But it is your custom that I release to you one prisoner at the Passover. So then, do you want me to release to you the King of the Jews?\u201d John 18:40  \u201cNot this man,\u201d they shouted, \u201cbut Barabbas!\u201d (Now Barabbas was an insurrectionist.)</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_18.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_19.html","title":"John 19","text":"<p>John 19:1   Then Pilate took Jesus and had Him flogged. John 19:2   The soldiers twisted together a crown of thorns, set it on His head, and dressed Him in a purple robe. John 19:3   And they went up to Him again and again, saying, \u201cHail, King of the Jews!\u201d and slapping Him in the face. John 19:4   Once again Pilate came out and said to the Jews, \u201cLook, I am bringing Him out to you to let you know that I find no basis for a charge against Him.\u201d John 19:5   When Jesus came out wearing the crown of thorns and the purple robe, Pilate said to them, \u201cHere is the man!\u201d John 19:6   As soon as the chief priests and officers saw Him, they shouted, \u201cCrucify Him! Crucify Him!\u201d \u201cYou take Him and crucify Him,\u201d Pilate replied, \u201cfor I find no basis for a charge against Him.\u201d John 19:7   \u201cWe have a law,\u201d answered the Jews, \u201cand according to that law He must die, because He declared Himself to be the Son of God.\u201d John 19:8   When Pilate heard this statement, he was even more afraid, John 19:9   and he went back into the Praetorium. \u201cWhere are You from?\u201d he asked. But Jesus gave no answer. John 19:10  So Pilate said to Him, \u201cDo You refuse to speak to me? Do You not know that I have authority to release You and authority to crucify You?\u201d John 19:11  Jesus answered, \u201cYou would have no authority over Me if it were not given to you from above. Therefore the one who handed Me over to you is guilty of greater sin.\u201d John 19:12  From then on, Pilate tried to release Him, but the Jews kept shouting, \u201cIf you release this man, you are no friend of Caesar. Anyone who declares himself a king is defying Caesar.\u201d John 19:13  When Pilate heard these words, he brought Jesus out and sat on the judgment seat at a place called the Stone Pavement, which in Hebrew is Gabbatha. John 19:14  It was the day of Preparation for the Passover, about the sixth hour. And Pilate said to the Jews, \u201cHere is your King!\u201d John 19:15  At this, they shouted, \u201cAway with Him! Away with Him! Crucify Him!\u201d \u201cShall I crucify your King?\u201d Pilate asked. \u201cWe have no king but Caesar,\u201d replied the chief priests. John 19:16  Then Pilate handed Jesus over to be crucified, and the soldiers took Him away. John 19:17  Carrying His own cross, He went out to The Place of the Skull, which in Hebrew is called Golgotha. John 19:18  There they crucified Him, and with Him two others, one on each side, with Jesus in the middle. John 19:19  Pilate also had a notice posted on the cross. It read: JESUS OF NAZARETH, THE KING OF THE JEWS. John 19:20  Many of the Jews read this sign, because the place where Jesus was crucified was near the city, and it was written in Hebrew, Latin, and Greek. John 19:21  So the chief priests of the Jews said to Pilate, \u201cDo not write, \u2018The King of the Jews,\u2019 but only that He said, \u2018I am the King of the Jews.\u2019\u201d John 19:22  Pilate answered, \u201cWhat I have written, I have written.\u201d John 19:23  When the soldiers had crucified Jesus, they divided His garments into four parts, one for each soldier, with the tunic remaining. It was seamless, woven in one piece from top to bottom. John 19:24  So they said to one another, \u201cLet us not tear it. Instead, let us cast lots to see who will get it.\u201d This was to fulfill the Scripture: \u201cThey divided My garments among them, and cast lots for My clothing.\u201d So that is what the soldiers did. John 19:25  Near the cross of Jesus stood His mother and her sister, as well as Mary the wife of Clopas and Mary Magdalene. John 19:26  When Jesus saw His mother and the disciple whom He loved standing nearby, He said to His mother, \u201cWoman, here is your son.\u201d John 19:27  Then He said to the disciple, \u201cHere is your mother.\u201d So from that hour, this disciple took her into his home. John 19:28  After this, knowing that everything had now been accomplished, and to fulfill the Scripture, Jesus said, \u201cI am thirsty.\u201d John 19:29  A jar of sour wine was sitting there. So they soaked a sponge in the wine, put it on a stalk of hyssop, and lifted it to His mouth. John 19:30  When Jesus had received the sour wine, He said, \u201cIt is finished.\u201d And bowing His head, He yielded up His spirit. John 19:31  It was the day of Preparation, and the next day was a High Sabbath. In order that the bodies would not remain on the cross during the Sabbath, the Jews asked Pilate to have the legs broken and the bodies removed. John 19:32  So the soldiers came and broke the legs of the first man who had been crucified with Jesus, and those of the other. John 19:33  But when they came to Jesus and saw that He was already dead, they did not break His legs. John 19:34  Instead, one of the soldiers pierced His side with a spear, and immediately blood and water flowed out. John 19:35  The one who saw it has testified to this, and his testimony is true. He knows that he is telling the truth, so that you also may believe. John 19:36  Now these things happened so that the Scripture would be fulfilled: \u201cNot one of His bones will be broken.\u201d John 19:37  And, as another Scripture says: \u201cThey will look on the One they have pierced.\u201d John 19:38  Afterward, Joseph of Arimathea, who was a disciple of Jesus (but secretly for fear of the Jews), asked Pilate to let him remove the body of Jesus. Pilate gave him permission, so he came and removed His body. John 19:39  Nicodemus, who had previously come to Jesus at night, also brought a mixture of myrrh and aloes, about seventy-five pounds. John 19:40  So they took the body of Jesus and wrapped it in linen cloths with the spices, according to the Jewish burial custom. John 19:41  Now there was a garden in the place where Jesus was crucified, and in the garden a new tomb in which no one had yet been laid. John 19:42  And because it was the Jewish day of Preparation and the tomb was nearby, they placed Jesus there.</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_19.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_20.html","title":"John 20","text":"<p>John 20:1   Early on the first day of the week, while it was still dark, Mary Magdalene went to the tomb and saw that the stone had been removed from the entrance. John 20:2   So she came running to Simon Peter and the other disciple, the one whom Jesus loved. \u201cThey have taken the Lord out of the tomb,\u201d she said, \u201cand we do not know where they have put Him!\u201d John 20:3   Then Peter and the other disciple set out for the tomb. John 20:4   The two were running together, but the other disciple outran Peter and reached the tomb first. John 20:5   He bent down and looked in at the linen cloths lying there, but he did not go in. John 20:6   Simon Peter arrived just after him. He entered the tomb and saw the linen cloths lying there. John 20:7   The cloth that had been around Jesus\u2019 head was rolled up, lying separate from the linen cloths. John 20:8   Then the other disciple, who had reached the tomb first, also went in. And he saw and believed. John 20:9   For they still did not understand from the Scripture that Jesus had to rise from the dead. John 20:10  Then the disciples returned to their homes. John 20:11  But Mary stood outside the tomb weeping. And as she wept, she bent down to look into the tomb, John 20:12  and she saw two angels in white sitting where the body of Jesus had lain, one at the head and the other at the feet. John 20:13  \u201cWoman, why are you weeping?\u201d they asked. \u201cBecause they have taken my Lord away,\u201d she said, \u201cand I do not know where they have put Him.\u201d John 20:14  When she had said this, she turned around and saw Jesus standing there. But she did not recognize that it was Jesus. John 20:15  \u201cWoman, why are you weeping?\u201d Jesus asked. \u201cWhom are you seeking?\u201d Thinking He was the gardener, she said, \u201cSir, if you have carried Him off, tell me where you have put Him, and I will get Him.\u201d John 20:16  Jesus said to her, \u201cMary.\u201d She turned and said to Him in Hebrew, \u201cRabboni!\u201d (which means \u201cTeacher\u201d). John 20:17  \u201cDo not cling to Me,\u201d Jesus said, \u201cfor I have not yet ascended to the Father. But go and tell My brothers, \u2018I am ascending to My Father and your Father, to My God and your God.\u2019\u201d John 20:18  Mary Magdalene went and announced to the disciples, \u201cI have seen the Lord!\u201d And she told them what He had said to her. John 20:19  It was the first day of the week, and that very evening, while the disciples were together with the doors locked for fear of the Jews, Jesus came and stood among them. \u201cPeace be with you!\u201d He said to them. John 20:20  After He had said this, He showed them His hands and His side. The disciples rejoiced when they saw the Lord. John 20:21  Again Jesus said to them, \u201cPeace be with you. As the Father has sent Me, so also I am sending you.\u201d John 20:22  When He had said this, He breathed on them and said, \u201cReceive the Holy Spirit. John 20:23  If you forgive anyone his sins, they are forgiven; if you withhold forgiveness from anyone, it is withheld.\u201d John 20:24  Now Thomas called Didymus, one of the Twelve, was not with the disciples when Jesus came. John 20:25  So the other disciples told him, \u201cWe have seen the Lord!\u201d But he replied, \u201cUnless I see the nail marks in His hands, and put my finger where the nails have been, and put my hand into His side, I will never believe.\u201d John 20:26  Eight days later, His disciples were once again inside with the doors locked, and Thomas was with them. Jesus came and stood among them and said, \u201cPeace be with you.\u201d John 20:27  Then Jesus said to Thomas, \u201cPut your finger here and look at My hands. Reach out your hand and put it into My side. Stop doubting and believe.\u201d John 20:28  Thomas replied, \u201cMy Lord and my God!\u201d John 20:29  Jesus said to him, \u201cBecause you have seen Me, you have believed; blessed are those who have not seen and yet have believed.\u201d John 20:30  Jesus performed many other signs in the presence of His disciples, which are not written in this book. John 20:31  But these are written so that you may believe that Jesus is the Christ, the Son of God, and that by believing you may have life in His name.</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_20.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_21.html","title":"John 21","text":"<p>John 21:1   Later, by the Sea of Tiberias, Jesus again revealed Himself to the disciples. He made Himself known in this way: John 21:2   Simon Peter, Thomas called Didymus, Nathanael from Cana in Galilee, the sons of Zebedee, and two other disciples were together. John 21:3   Simon Peter told them, \u201cI am going fishing.\u201d \u201cWe will go with you,\u201d they said. So they went out and got into the boat, but caught nothing that night. John 21:4   Early in the morning, Jesus stood on the shore, but the disciples did not recognize that it was Jesus. John 21:5   So He called out to them, \u201cChildren, do you have any fish?\u201d \u201cNo,\u201d they answered. John 21:6   He told them, \u201cCast the net on the right side of the boat, and you will find some.\u201d So they cast it there, and they were unable to haul it in because of the great number of fish. John 21:7   Then the disciple whom Jesus loved said to Peter, \u201cIt is the Lord!\u201d As soon as Simon Peter heard that it was the Lord, he put on his outer garment (for he had removed it) and jumped into the sea. John 21:8   The other disciples came ashore in the boat. They dragged in the net full of fish, for they were not far from land, only about a hundred yards. John 21:9   When they landed, they saw a charcoal fire there with fish on it, and some bread. John 21:10  Jesus told them, \u201cBring some of the fish you have just caught.\u201d John 21:11  So Simon Peter went aboard and dragged the net ashore. It was full of large fish, 153, but even with so many, the net was not torn. John 21:12  \u201cCome, have breakfast,\u201d Jesus said to them. None of the disciples dared to ask Him, \u201cWho are You?\u201d They knew it was the Lord. John 21:13  Jesus came and took the bread and gave it to them, and He did the same with the fish. John 21:14  This was now the third time that Jesus appeared to the disciples after He was raised from the dead. John 21:15  When they had finished eating, Jesus asked Simon Peter, \u201cSimon son of John, do you love Me more than these?\u201d \u201cYes, Lord,\u201d he answered, \u201cYou know I love You.\u201d Jesus replied, \u201cFeed My lambs.\u201d John 21:16  Jesus asked a second time, \u201cSimon son of John, do you love Me?\u201d \u201cYes, Lord,\u201d he answered, \u201cYou know I love You.\u201d Jesus told him, \u201cShepherd My sheep.\u201d John 21:17  Jesus asked a third time, \u201cSimon son of John, do you love Me?\u201d Peter was deeply hurt that Jesus had asked him a third time, \u201cDo you love Me?\u201d \u201cLord, You know all things,\u201d he replied. \u201cYou know I love You.\u201d Jesus said to him, \u201cFeed My sheep. John 21:18  Truly, truly, I tell you, when you were young, you dressed yourself and walked where you wanted; but when you are old, you will stretch out your hands, and someone else will dress you and lead you where you do not want to go.\u201d John 21:19  Jesus said this to indicate the kind of death by which Peter would glorify God. And after He had said this, He told him, \u201cFollow Me.\u201d John 21:20  Peter turned and saw the disciple whom Jesus loved following them. He was the one who had leaned back against Jesus at the supper to ask, \u201cLord, who is going to betray You?\u201d John 21:21  When Peter saw him, he asked, \u201cLord, what about him?\u201d John 21:22  Jesus answered, \u201cIf I want him to remain until I return, what is that to you? You follow Me!\u201d John 21:23  Because of this, the rumor spread among the brothers that this disciple would not die. However, Jesus did not say that he would not die, but only, \u201cIf I want him to remain until I return, what is that to you?\u201d John 21:24  This is the disciple who testifies to these things and who has written them down. And we know that his testimony is true. John 21:25  There are many more things that Jesus did. If all of them were written down, I suppose that not even the world itself would have space for the books that would be written.</p>","tags":["type-bible","source"]},{"location":"Bible/John/John_21.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-bible","source"]},{"location":"MOC/How_to_Take_Smart_Notes.html","title":"How to Take Smart Notes","text":"<p>This book is foundational for how I capture and connect ideas.</p> <p></p> <ul> <li>Author: S\u00f6nke Ahrens</li> <li>Full Title: How to Take Smart Notes</li> <li>Publication Date: February 24, 2017</li> <li>https://www.amazon.com/dp/1542866502</li> </ul>","tags":["type-auto-moc","source-book","thinking","note-taking","writing-as-thinking","clarity-of-thought"]},{"location":"MOC/How_to_Take_Smart_Notes.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-auto-moc","source-book","thinking","note-taking","writing-as-thinking","clarity-of-thought"]},{"location":"MOC/Inductive_Bible_Study_Method.html","title":"Inductive Bible Study Method","text":"<p>The Inductive Bible Study method is all about slowing down and paying attention to the passage you're reading, letting Scripture speak for itself. You don't start with a big theology you\u2019re trying to fit things into. Instead, you let your understanding grow as you study each passage.</p> <p>If you want to dive deeper into how this works, I talk more about the inductive process in these articles.</p> <ul> <li>Understanding presuppositions in Bible study</li> <li>Observe what this passage says</li> <li>Interpret what this passage means</li> <li>Apply Bible study to your life</li> <li>Zettelkasten and Inductive Bible Study</li> </ul>","tags":["type-auto-moc"]},{"location":"MOC/Inductive_Bible_Study_Method.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-auto-moc"]},{"location":"MOC/Signs_in_John.html","title":"Signs in John","text":"<p>John organizes his Gospel around key signs that reveal Jesus\u2019 glory and lead to belief. This note will link to my notes about these signs.</p> <ul> <li>The Gospel of John</li> </ul>","tags":["type-auto-moc"]},{"location":"MOC/Signs_in_John.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-auto-moc"]},{"location":"MOC/The_Gospel_of_John.html","title":"The Gospel of John","text":"<p>This MOC tracks the structure, themes, and signs in John\u2019s Gospel to support study and linking across passages.</p> <ul> <li>Who Wrote the Gospel of John, and Why Does It Matter?</li> <li>Why Did John Write This Gospel?</li> <li>Signs in John</li> </ul>","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#in-the-beginning-was-the-word-1118","title":"In the Beginning Was the Word (1:1\u201318)","text":"<ul> <li>The Word Became Flesh</li> </ul>","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#come-and-see-119-454","title":"Come and See (1:19-4:54)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#john-the-baptists-testimony-john-119-34","title":"John the Baptist\u2019s Testimony (John 1:19-34)","text":"<ul> <li>A Voice After Silence</li> <li>The Lamb of God</li> </ul>","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#the-first-disciples-drawn-13551","title":"The first disciples drawn (1:35\u201351)","text":"<ul> <li>Jesus: Connecting Heaven and Earth</li> </ul>","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#the-wedding-at-cana-john-2111","title":"The Wedding at Cana (John 2:1\u201311)","text":"<ul> <li>The Wedding at Cana</li> <li>Signs in John</li> </ul>","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#zeal-for-my-fathers-house-212225","title":"Zeal for My Father\u2019s House (2:12\u20132:25)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#unless-one-is-born-again-31321","title":"Unless One Is Born Again (3:1\u20133:21)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#he-must-increase-32236","title":"He Must Increase (3:22\u201336)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#living-water-4142","title":"Living Water (4:1\u201342)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#your-son-will-live-44354","title":"Your Son Will Live (4:43\u201354)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#that-the-works-of-god-might-be-displayed-511250","title":"That the Works of God Might Be Displayed (5:1\u201312:50)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#do-you-want-to-be-healed-5147","title":"Do You Want to Be Healed? (5:1\u201347)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#i-am-the-bread-of-life-6171","title":"I Am the Bread of Life (6:1\u201371)","text":"<ul> <li>Wrestling with John 6: The Father, the Son, and the Struggle to Believe</li> </ul>","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#a-boy-with-five-barley-loaves-and-two-small-fish-61-15","title":"A Boy With Five Barley Loaves and Two Small Fish (6:1-15)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#it-is-i-do-not-be-afraid-616-21","title":"It is I; Do Not be Afraid (6:16-21)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#looking-for-me-because-you-ate-622-27","title":"Looking For Me Because You Ate (6:22-27)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#the-true-bread-from-heaven-628-34","title":"The True Bread From Heaven (6:28-34)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#whoever-comes-to-me-will-never-hunger-635-40","title":"Whoever Comes to Me Will Never Hunger (6:35-40)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#anyone-may-eat-of-it-and-not-die-641-59","title":"Anyone May Eat of It And Not Die (6:41-59)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#who-can-accept-it-660-71","title":"Who Can Accept It? (6:60-71)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#my-time-has-not-yet-come-7152","title":"My Time Has Not Yet Come (7:1\u201352)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#neither-do-i-condemn-you-753811","title":"Neither Do I Condemn You (7:53\u20138:11)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#i-am-the-light-of-the-world-812859","title":"I Am the Light of the World (8:12\u20138:59)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#that-the-works-of-god-might-be-displayed-9141","title":"That the Works of God Might Be Displayed (9:1\u201341)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#i-am-the-good-shepherd-10142","title":"I Am the Good Shepherd (10:1\u201342)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#i-am-the-resurrection-and-the-life-11157","title":"I Am the Resurrection and the Life (11:1\u201357)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#the-hour-has-come-12150","title":"The Hour Has Come (12:1\u201350)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#abide-in-me-131-1726","title":"Abide in Me (13:1-17:26)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#having-loved-his-own-13138","title":"Having Loved His Own (13:1\u201338)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#i-am-the-way-the-truth-and-the-life-14131","title":"I Am the Way, the Truth, and the Life (14:1\u201331)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#i-am-the-true-vine-15127","title":"I Am the True Vine (15:1\u201327)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#take-heart-i-have-overcome-the-world-16133","title":"Take Heart; I Have Overcome the World (16:1\u201333)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#that-they-may-be-one-17126","title":"That They May Be One (17:1\u201326)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#it-is-finished-181-2029","title":"It Is Finished (18:1-20:29)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#shall-i-not-drink-the-cup-1811916","title":"Shall I Not Drink the Cup? (18:1\u201319:16)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#it-is-finished-191742","title":"It Is Finished (19:17\u201342)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#i-have-seen-the-lord-20129","title":"I Have Seen the Lord (20:1\u201329)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#that-you-may-believe-203031","title":"That You May Believe (20:30\u201331)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#do-you-love-me-21123","title":"Do You Love Me? (21:1\u201323)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#this-is-the-disciple-who-testifies-2124-25","title":"This Is the Disciple Who Testifies (21:24-25)","text":"","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/The_Gospel_of_John.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-structural","source-book","bible-outline"]},{"location":"MOC/Zettelkasten.html","title":"Zettelkasten","text":"<p>This note will link to my notes about my Zettelkasten.</p>","tags":["type-auto-moc"]},{"location":"MOC/Zettelkasten.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-auto-moc"]},{"location":"articles/Apply_Bible_study_to_your_life.html","title":"Apply Bible study to your life","text":"<p>Once you\u2019ve\u00a0Observe what this passage says and Interpret what this passage means, the final step in Bible study is application, asking, \u201cSo what?\u201d This is where your study becomes personal. Without application, all your effort in understanding what the author said remains just head knowledge. It doesn\u2019t benefit you or anyone else until it transforms how you live, think, and relate to God and others.</p> <p>Begin by asking how the message applied to the original audience. What was their situation? What challenges or circumstances were they facing? Not everything in the text will apply to us in exactly the same way, so it\u2019s important to recognize what is unique to their time, place, and context.</p> <p>Then, look for universal truths that apply to all people, in every place and time. These are the principles that can bridge the gap between the ancient world and our own. From there, consider how these truths speak to a modern audience, and more personally, how they apply to you.</p> <p>Application isn\u2019t just about what you should do; it\u2019s also about what and how you should think. Scripture speaks to our actions, yes, but it also reshapes our beliefs, perspectives, and desires. As you apply God\u2019s Word, let it guide how you live and how you view the world around you.</p> <p>Finally, be patient with the process. Don\u2019t rush to application too soon. Take the time to fully understand the passage before asking what to do with it. Let Scripture sink in. When you let God\u2019s Word shape your heart and mind, real transformation begins from the inside out.</p>","tags":["type-article"]},{"location":"articles/Apply_Bible_study_to_your_life.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"articles/Ephesians_Purpose.html","title":"Why Did Paul Write the Letter to the Ephesians?","text":"<p>Paul tells us plainly why he wrote his letter to the Ephesians. In Ephesians 4:1, he writes:</p> <p>I urge you to walk in a manner worthy of the calling you have received.</p> <p>Paul is encouraging believers to live in a way that reflects the calling they received when they placed their faith in Jesus. He begins the letter by reminding them of all the blessings they received in Christ. Then he shifts to instructing them on how to live in response to those blessings. Much like Why Did James Write This Letter?, Paul calls believers not only to believe but also to live out their faith in daily life.</p>","tags":["type-article"]},{"location":"articles/Ephesians_Purpose.html#blessed-in-christ","title":"Blessed in Christ","text":"<p>Paul opens the letter by describing the incredible blessings believers have received in Christ. God has poured out His glorious grace on us \"in the Beloved One.\" He has given us redemption and forgiveness, not only to the Israelites but also to the Gentiles. This inclusion of the Gentiles reveals a mystery that had been hidden for ages: salvation through Christ is available to all.</p> <p>Even though they were once spiritually dead in sin, they have now been saved through faith. This salvation is not something they could earn. It is a gift from God, so no one can boast. Because of Jesus, Gentile believers are \"no longer strangers and foreigners, but fellow citizens with the saints and members of God\u2019s household.\" In Christ, both Jews and Gentiles are united as one people. Through all of this, God\u2019s great love has been made known. Paul prays that believers would truly grasp how vast and deep that love is.</p>","tags":["type-article"]},{"location":"articles/Ephesians_Purpose.html#walk-in-a-worthy-manner","title":"Walk in a Worthy Manner","text":"<p>In light of all that God has done, Paul urges the Ephesians to live in a way that reflects their new identity. He calls them to unity, especially between Jewish and Gentile believers. They are not to be spiritually immature or easily swayed by false teachings. Instead, they are to speak the truth, grow in their faith, and become more like Christ.</p> <p>Paul encourages them to leave behind their old way of living and to \"put on the new self.\" This new life involves renewing their minds, showing love and forgiveness, and imitating God. They are to live in right relationship with one another, both in their families and in the workplace. Rather than being controlled by anything else, they are to be filled with the Spirit.</p> <p>Paul reminds them that God has equipped them with everything they need: truth, righteousness, faith, Scripture, and salvation. With these gifts, along with constant prayer, they can walk in a manner worthy of the calling they received when they first believed.</p>","tags":["type-article"]},{"location":"articles/Ephesians_Purpose.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"articles/Galatians_Purpose.html","title":"Why Did Paul Write the Letter to the Galatians?","text":"<p>Early in the letter, Paul expresses his amazement at how quickly the churches in Galatia were turning to a different message (Galatians 1:6):</p> <p>I am amazed how quickly you are deserting the One who called you by the grace of Christ and are turning to a different gospel.</p> <p>This concern that the Galatians are turning from the true gospel to a different gospel is the central focus of the entire letter.</p>","tags":["type-article"]},{"location":"articles/Galatians_Purpose.html#the-concern","title":"The Concern","text":"<p>Paul begins by reminding the Galatians that Jesus Christ gave Himself for our sins. He then addresses his main concern: they are turning away from the true gospel. Certain individuals had come among them and were distorting the message of Christ. Specifically, they were teaching that faith in Jesus was not enough and that believers must also follow the law, including circumcision, to be fully accepted by God.</p>","tags":["type-article"]},{"location":"articles/Galatians_Purpose.html#the-source-of-pauls-gospel","title":"The Source of Paul's Gospel","text":"<p>To explain why this is wrong, Paul reminds them of his own story. He had once persecuted the church and was deeply committed to Judaism, but God called him to preach the gospel to the Gentiles. Paul points out that the message he preached did not come from any human source. He received it directly from Jesus Christ.</p>","tags":["type-article"]},{"location":"articles/Galatians_Purpose.html#pauls-gospel-confirmed","title":"Paul's Gospel Confirmed","text":"<p>Later, Paul visited Jerusalem and met with Peter and James. They recognized his mission to the Gentiles as equal to Peter\u2019s mission to the Jews. They did not require Titus, a Gentile, to be circumcised. Paul also describes how he confronted Peter for withdrawing from Gentile believers when other Jews arrived. Paul\u2019s point is that even Jewish apostles had stopped relying on the law once they fully understood the gospel. They did not expect Gentile believers to follow Jewish customs. As Paul explains, \u201cIf righteousness comes through the law, then Christ died for nothing.\u201d</p>","tags":["type-article"]},{"location":"articles/Galatians_Purpose.html#the-gospel-applied","title":"The Gospel Applied","text":"<p>Paul then turns back to the Galatians and questions why they would start by faith and then try to continue by following the law. He reminds them that Abraham was declared righteous because of his faith, not because of his actions. Abraham had also received the promise that \u201cAll nations will be blessed through you,\u201d a promise that extends to those who believe. Paul warns that those who rely on the law are under a curse, while those who belong to Christ are the true children of Abraham. He expresses concern that the Galatians are exchanging faith for a system that was never meant to bring salvation.</p> <p>Paul closes the letter by urging the Galatians to use their freedom in Christ Why Did James Write This Letter?. They were not set free to indulge selfish desires but to love and serve one another. He encourages them to walk by the Spirit rather than follow their old nature. When they live this way, their lives will produce the fruit of the Spirit and reflect the new life they have in Christ.</p>","tags":["type-article"]},{"location":"articles/Galatians_Purpose.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"articles/Interpret_what_this_passage_means.html","title":"Interpret what this passage means","text":"<p>Once you've carefully  Observe what this passage says and come to terms with what the author is saying, the next step is interpretation, seeking to understand what the passage means. This involves uncovering the author's intent, argument, and main points. It's crucial during this stage to set aside your own opinions, assumptions, and theological preferences as much as possible. Let the author, both human and divine, speak for themselves.</p> <p>Start by asking: What was the author\u2019s original purpose in writing this? What argument are they making? What themes or key points are they trying to get across? Your goal is to discover what the text meant to its original audience and how that meaning unfolds within the larger context of Scripture.</p> <p>The Observe what this passage says still apply here. You should still avoid adding anything to the passage that isn't there, and you shouldn\u2019t ignore or minimize things that are there. Watch out for common pitfalls, like the negative inference fallacy, drawing conclusions from what isn\u2019t said, rather than focusing on what is. Stay grounded in the text, and let the author\u2019s priorities shape your interpretation. Make sure the main thing remains the main thing.</p> <p>Part of interpreting a passage well means understanding how it fits within the broader text. Where does it fall in the flow of the author\u2019s argument? What came before it? What follows? Pay attention to how key words and ideas are used elsewhere both by the same author and by other biblical writers. When a word or phrase appears in multiple contexts, compare how it functions in each. Remember, words can have multiple meanings, so the same word may not mean the same thing in different contexts.</p> <p>Sometimes New Testament authors interpret and apply Old Testament texts in ways that expand or deepen the original understanding. Even if their interpretation reveals a meaning that the Old Testament authors or readers may not have fully grasped, the New Testament interpretation is still correct. These writers were just as inspired by God as the Old Testament authors, and God\u2019s intended meaning was always present, even if the human authors didn\u2019t fully understand it at the time.</p> <p>Understanding the sequence of events in a passage is also helpful. What\u2019s happening in the narrative timeline, and how does this passage connect to the events before and after it? Asking questions like \u201cWhy did the author include this?\u201d or \u201cWhat is the significance of this detail?\u201d can reveal deeper layers of meaning. Consider where the event falls in history\u2014was it before or after God called Israel? Before or after Jesus\u2019 death, burial, and resurrection? These time markers, along with other major events, can greatly influence how we understand the text.</p> <p>It\u2019s also important to think about the genre. Some biblical stories contain a deeper or symbolic meaning beyond the surface called an allegory. But be careful, don't Understanding presuppositions in Bible study something is allegorical unless the author or speaker clearly indicates it. If it is, then explore the allegorical meaning thoughtfully.</p> <p>Ultimately, interpretation is about understanding the heart of the message\u2014not just what is said, but why it\u2019s said, and how it contributes to the bigger picture of God\u2019s revelation.</p>","tags":["type-article"]},{"location":"articles/Interpret_what_this_passage_means.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"articles/James_purpose.html","title":"Why Did James Write This Letter?","text":"<p>At the beginning of his letter, James states his purpose clearly (James 1:2\u20134):</p> <p>Consider it pure joy, my brothers, when you encounter trials of many kinds, because you know that the testing of your faith develops perseverance. Allow perseverance to finish its work, so that you may be mature and complete, not lacking anything.</p> <p>James writes to encourage believers to respond to trials with joy, viewing them not as setbacks but as opportunities for growth. These trials, he explains, are tests of faith. They develop perseverance, which in turn leads to maturity. Right from the start, James outlines the process: enduring trials with the right perspective leads to spiritual growth. The rest of the letter expands on this theme, providing examples of the types of trials believers face and how these experiences develop perseverance and maturity. Ultimately, James calls his readers to live out their faith in tangible ways, reminding them that \u201cfaith by itself, if it does not result in action, is dead.\u201d</p>","tags":["type-article"]},{"location":"articles/James_purpose.html#how-to-approach-trials","title":"How to Approach Trials","text":"<p>Immediately after introducing the idea of trials, James provides guidance on how to navigate them: with wisdom. He emphasizes the need for wisdom that comes from God, implying that human wisdom alone is insufficient for handling the challenges believers will encounter. Fortunately, James assures his readers that God gives generously to those who ask and does so without reproach.</p> <p>However, receiving wisdom requires faith. James warns that those who doubt will struggle, being like a wave of the sea, driven and tossed by the wind. Just as John emphasized the need to Why Did John Write This Gospel?, James emphasizes the necessity of faith when asking for wisdom. Without faith, double-mindedness results in instability.</p>","tags":["type-article"]},{"location":"articles/James_purpose.html#trials-lead-to-maturity","title":"Trials Lead to Maturity","text":"<p>Many of the trials James references are related to how believers treat one another. For instance, he addresses issues such as favoritism toward the wealthy and disregard for the poor. Instead of making such distinctions, believers are called to treat all people with equal dignity and respect. Furthermore, James instructs his readers not merely to offer kind words to those in need but to take tangible action to help.</p> <p>Other examples of maturity include controlling one's speech, avoiding quarrels, and resisting envy. These behaviors reflect spiritual growth and demonstrate the wisdom James promotes. His teaching aligns with the command to \"love your neighbor as yourself,\" highlighting how relationships and community are central to mature Christian living.</p>","tags":["type-article"]},{"location":"articles/James_purpose.html#trials-lead-to-perseverance","title":"Trials Lead to Perseverance","text":"<p>James also explores how trials serve to strengthen faith. Trials can tempt believers to doubt or turn away, but James reminds his readers that faith is not only the means of receiving eternal life but also the means by which we receive wisdom and endure trials.</p> <p>True, living faith results in action. If a person truly believes that God is who He says He is and will do what He has promised, then that faith will be evident in how they live. James supports this claim by pointing to examples such as Abraham, Job, Rahab, and the prophets. Each faced significant trials but remained faithful, trusting in God's character and promises. James summarizes this idea forcefully by stating that \"faith by itself, if it does not result in action, is dead.\"</p>","tags":["type-article"]},{"location":"articles/James_purpose.html#when-we-fail-a-trial","title":"When We Fail a Trial","text":"<p>James also addresses the reality that believers will not always succeed in facing trials. He writes that if someone wanders from the truth, another believer should seek to bring that person back. Failure in a trial may lead to sin or a temporary departure from faithful living, but restoration is possible.</p> <p>James does not expect perfection. He acknowledges that all believers stumble at times, yet calls the Christian community to respond with care, accountability, and encouragement. Helping one another return to the truth is an essential aspect of life together in the faith.</p>","tags":["type-article"]},{"location":"articles/James_purpose.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"articles/John_1_1-18_The_Word_Became_Flesh.html","title":"The Word Became Flesh","text":"<p>In John 1:1\u201318 we encounter the major themes of the Gospel as Jesus is revealed to be the eternal Word, the Creator, the Light, the Life, and the One who reveals the Father. John shows us who Jesus is and why He came. He calls every reader to make a choice: receive Him or reject Him.\u00a0This passage reveals who Jesus is, what He came to do, how witnesses confirmed Him, and how we are to respond.</p>","tags":["type-article"]},{"location":"articles/John_1_1-18_The_Word_Became_Flesh.html#the-word-as-god-and-creator","title":"The Word as God and Creator","text":"<p>John opens with \"in the beginning was the Word\".\u00a0This is reminiscent of Genesis 1 where \"in the beginning\" God spoke (using words) creation into existence.\u00a0Jesus is the eternal Word (the logos) of God. By using the word logos to identify Jesus, John might have also had the Greeks, who were very philosophical, in mind since logos can also mean thinking and reasoning.</p> <p>The Word was with God and the Word was God. From the start, John presents the Word as both divine and yet somehow distinct from God. This becomes clearer when John tells us that He is the Son who came from the Father. The Son and the Father are both God, yet they are distinct from each other.</p> <p>The link to Genesis 1 is strengthened when John tells us that the Word created everything. He was not created. In fact, there was nothing created that He did not create. Some, like the Jehovah's Witnesses, claim that Jesus was a created being. But John excludes that possibility. If it was made, He made it. Jesus is the uncreated Creator.</p> <p>The Word does not just create the world and then walk away leaving His creation to its own devices. The Word is directly involved in the world, revealing God and making Him known.</p>","tags":["type-article"]},{"location":"articles/John_1_1-18_The_Word_Became_Flesh.html#life-and-light-in-the-word","title":"Life and Light in the Word","text":"<p>After establishing the Word as both God and Creator, John moves from the Word's identity to His mission. In Him was life. Life that is eternal because He is eternal. And that life was the Light of the world, revealing what is hidden, shining in the darkness. Jesus is the source of all life and the One who makes the Father known. The Word is not just God and Creator. He is the Light shining in the darkness. And the darkness has not overcome it.</p>","tags":["type-article"]},{"location":"articles/John_1_1-18_The_Word_Became_Flesh.html#the-word-became-flesh_1","title":"The Word Became Flesh","text":"<p>The Word did not just come as the Light. He was not just revealing truth about God. No, He came in flesh, dwelling on the earth as a man. Jesus was not a spiritual being manifesting as a man. He did not suddenly appear as a fully grown man. He had a physical body just like we do. As we learn in the other gospels, He was born and He grew. He lived a life just like every other person.</p> <p>Except Jesus was different from other people. While He really was a man, He was not merely a man. He was the Son from the Father who had seen the Father and came to make the Father know. No one has ever seen God. The only Son, who is Himself God and is at the Father's side, has made Him known. From the very beginning of John's Gospel, we are introduced to the man Jesus as the Word, the Creator, God Himself, the Light, the source of life, the Son from the Father, who came to reveal the Father.</p>","tags":["type-article"]},{"location":"articles/John_1_1-18_The_Word_Became_Flesh.html#the-witnesses","title":"The Witnesses","text":"<p>After introducing the Word, John introduces us to another man named John who was sent to bear witness to the Light. Throughout his gospel, John is careful to present multiple witnesses to testify about Jesus. John the Baptist is the first.</p> <p>Apparently, there was some confusion about who John the Baptist was. Some thought he might have been the Messiah, but he denied that. He made it clear that he was not the Messiah or the Light. He was the prophet sent to testify about the Light, crying out for all to hear, \u201cThis is He of whom I said, 'He who comes after me has surpassed me because He was before me.'\u201d John was a witness to who Jesus was as much as Jesus' miracles and teachings were.</p> <p>Just as John bore witness, so did the author as he\u00a0mentions his own qualifications to testify about the Light, the Word, the Christ, who came as the man Jesus. From Jesus, John, along with others, received grace upon grace as he lived with Jesus and learned from Him.</p>","tags":["type-article"]},{"location":"articles/John_1_1-18_The_Word_Became_Flesh.html#receiving-or-rejecting-the-light","title":"Receiving or Rejecting the Light","text":"<p>The Light that John testified about came into the world to reveal the Father to a dark world. Unfortunately, the world did not recognize Him. Even His own chosen people, who knew the Messiah was coming, did not receive Him.</p> <p>But not everyone rejected the Light. And all those who received the Light were given the right to become children of God. John does not leave us wondering how to receive the Light. It comes by believing in Him. And to those who did believe in Jesus, He gave the right to become children of God. Later we learn that by being children of God, we gain eternal life.</p> <p>Unlike Moses, who brought the law, Jesus came in grace and truth from the Father's side to make the Father known. The law of Moses revealed to the Jews who they were: sinners who could not live up to God's expectations. Jesus, on the other hand, revealed the Father. While fulfilling the law, Jesus also offered eternal life with the Father. By receiving Christ, we can become God's children, and Jesus' Father becomes our Father.</p> <p>From the very beginning of his Gospel, John focuses on the choice all of us have: receive Jesus or reject Him. This theme weaves through the entire Gospel. If fact later John later tells us why he wrote (see John's Purpose).</p>","tags":["type-article"]},{"location":"articles/John_1_1-18_The_Word_Became_Flesh.html#conclusion-believe-and-receive","title":"Conclusion: Believe and Receive","text":"<p>These themes permeate the rest of the Gospel, calling on us to believe in Jesus and, by believing, to receive Him and eternal life. The question remains for us as it did for them: will we receive Him?</p>","tags":["type-article"]},{"location":"articles/John_1_1-18_The_Word_Became_Flesh.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"articles/John_1_19-28_A_Voice_Calling_In_the_Wilderness.html","title":"A Voice After Silence","text":"<p>By the time the priests and Levites came to question John the Baptist in John 1:19\u201328, it had been nearly 400 years since God spoke to the Israelites through a prophet. The last prophet sent by God was Malachi, who prophesied the return of Elijah before the day of the Lord (Malachi 4:5-6). As his questioners learned, John exemplifies the humility and purpose of a true witness. He consistently pointed away from himself and toward the Messiah. In this passage we learn more about who John was and his mission to testify about the Light who became flesh.</p> <p>The people recognized John as a prophet and the masses came to him to hear what he preached and be baptized by him. As crowds flocked to John, the Jewish leaders wanted to find out who he was. They sent priests and Levites to question him. Finding John, they asked him if he was the Christ, Elijah, or the Prophet. John repeatedly denied being any of these just as he was described as not being the Light earlier John 1:6-8.</p>","tags":["type-article"]},{"location":"articles/John_1_19-28_A_Voice_Calling_In_the_Wilderness.html#a-voice-and-the-word","title":"A Voice and The Word","text":"<p>Growing impatient with his denials, John's questioners asked him who he is. At this point John responded \"I am a voice of one calling in the wilderness, \u2018Make straight the way for the Lord.\u2019\" John was identifying himself as the forerunner to the Messiah that Isaiah spoke of centuries earlier. By calling himself \"a voice\" rather than \"the voice\", John drew a distinction between himself and the Word he came to testify about.</p> <p>But the leaders weren\u2019t just interested in who he was. They also challenged his right to baptize. At this John quickly redirected them to the One he was sent to testify about. While he was preaching and baptizing with urgency preparing the people for Jesus' arrival, he still diminished his baptism as only \"with water\", quickly turning their attention to Jesus. John made two things clear to them: you don't know Him even though He stands among you, and that he, John, is not worthy to untie His sandals.</p>","tags":["type-article"]},{"location":"articles/John_1_19-28_A_Voice_Calling_In_the_Wilderness.html#recognizing-the-christ","title":"Recognizing the Christ","text":"<p>John tells these men that they do not recognize Jesus as the Christ, echoing the theme from the gospel's introduction where the world, and even His own people, did not recognize or receive Him (see The Word Became Flesh). The Christ, the One the Jews had been waiting for had arrived. They knew He was coming. They had been told what to look for. John was here testifying about Him. And yet they did not recognize Him and receive Him. John's witness shined light reveal who Jesus is, but they were not ready to receive it.</p> <p>He then explained to them that they really didn't know John either. They thought he was a great prophet or maybe even the Messiah, but in reality John was unworthy to untie Jesus' sandals. Compared to Jesus, John wasn't even worthy to be His lowest slave. Jesus is God incarnate. He is infinitely greater than John, even though John was prophesied about and was gaining a large following. John turned attention away from himself and toward Jesus.</p> <p>John's only mission was to point people to Jesus as the promised Messiah. And he remained faithful to it. What about us? Do we point people at ourselves or at Jesus? What do we have in our lives that gets in our way? What stops us from fully receiving Jesus and reflecting His light into the world?</p>","tags":["type-article"]},{"location":"articles/John_1_19-28_A_Voice_Calling_In_the_Wilderness.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"articles/John_1_29-34_The_Lamb_of_God.html","title":"The Lamb of God","text":"<p>In John 1:29-34 we learn more about who Jesus is. The day after the scribes and Levites questioned John, Jesus approached him. The very One John was sent to prepare the way for was now coming toward him. Without hesitation, John proclaimed, \u201cLook, the Lamb of God, who takes away the sin of the world!\u201d</p>","tags":["type-article"]},{"location":"articles/John_1_29-34_The_Lamb_of_God.html#takes-away-sin","title":"Takes Away Sin","text":"<p>By calling Jesus the Lamb of God, John evokes rich Old Testament imagery. In the Passover (Exodus 12), Israelite families in Egypt were spared God\u2019s judgment through the blood of a lamb. Lambs also played a central role in Israel\u2019s sacrificial system. Likewise, Isaiah foresaw a suffering servant who would be \u201clike a lamb led to the slaughter\u201d (Isaiah 53). In both this Gospel and in Revelation, John consistently calls Jesus the Lamb, a title that points to both His sacrifice and His triumph over sin and death.</p> <p>The phrase \u201ctakes away the sin of the world\u201d reveals the scope of Jesus\u2019 mission. He came not only for Israel but for the entire world. This does not mean that all people will automatically be saved, but that the offer of salvation is made to everyone. Later we learn that all who believe in Him will be given eternal life and become children born of God.</p>","tags":["type-article"]},{"location":"articles/John_1_29-34_The_Lamb_of_God.html#jesus-is-greater","title":"Jesus Is Greater","text":"<p>John then declared that Jesus is greater than he is, \u201cbecause He was before me.\u201d The Greek word protos, translated as \u201cbefore,\u201d can refer either to being first in time or first in rank. In Jesus\u2019 case, both are true. As the eternal The Word Became Flesh, Jesus existed before John. And as the Christ, He surpasses John in honor and authority. John had already A Voice After Silence the day before that he was not worthy even to untie Jesus\u2019 sandals.</p>","tags":["type-article"]},{"location":"articles/John_1_29-34_The_Lamb_of_God.html#recognizing-the-messiah","title":"Recognizing the Messiah","text":"<p>John continued, \u201cI myself did not know Him.\u201d This may sound confusing. We know from Luke\u2019s Gospel that John leapt in the womb when Mary visited Elizabeth. But John was not referring to personally recognizing Jesus. He was sent to prepare the way for the Messiah and needed a way to identify Him. God had told him, \u201cThe man on whom you see the Spirit descend and rest is He who will baptize with the Holy Spirit.\u201d Only when John saw the Spirit descend on Jesus did he know for certain that Jesus is the Son of God.</p> <p>Like John, we too cannot recognize Jesus rightly without God's help. As Jesus later says, \u201cNo one can come to Me unless the Father who sent Me draws him\u201d (Wrestling with John 6: The Father, the Son, and the Struggle to Believe).</p>","tags":["type-article"]},{"location":"articles/John_1_29-34_The_Lamb_of_God.html#the-spirit-who-remains","title":"The Spirit Who Remains","text":"<p>The Spirit descending and remaining on Jesus is significant. In the Old Testament, the Spirit would come upon individuals, but not necessarily remain. Saul lost the Spirit, and David prayed not to. But Jesus is different. The Spirit descended like a dove and remained on Him. Jesus is the one from whom the Spirit is given.</p> <p>Having recognized Jesus as the Messiah, John also compares their baptisms. While John baptized with water, Jesus would baptize with the Holy Spirit. This shows that Jesus is not only greater in rank but also in the power of His mission. Only Jesus can give the Spirit.</p>","tags":["type-article"]},{"location":"articles/John_1_29-34_The_Lamb_of_God.html#the-trinity-introduced","title":"The Trinity Introduced","text":"<p>This is the first time the Holy Spirit is mentioned in John\u2019s Gospel. Already we have been introduced to the Father, the Son, and the Holy Spirit. Each has a distinct role, yet all are fully God. While the idea of the Trinity will be developed more fully later, the foundation has already been laid: three distinct persons united as one.</p>","tags":["type-article"]},{"location":"articles/John_1_29-34_The_Lamb_of_God.html#johns-testimony","title":"John's Testimony","text":"<p>Jesus, the One on whom the Spirit descended, who surpasses John in every way, who is the Son of God, is the One John came to testify about. All of John\u2019s ministry was to humbly prepare everyone to recognize and receive Him.</p>","tags":["type-article"]},{"location":"articles/John_1_29-34_The_Lamb_of_God.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"articles/John_1_35-51_Jesus_Connecting_Heaven_and_Earth.html","title":"Jesus: Connecting Heaven and Earth","text":"<p>In John 1:35-51 we learn that Jesus came to bring all people to God. He is the ladder Jacob dreamed of, the Son of Man Daniel prophesied about, and the Lamb of God foreshadowed by the Jewish sacrificial system. The glory and magnitude of this revelation is so great that once we have learned and believed it, we cannot keep it to ourselves. We see this in John the Baptist, Andrew and Philip. All of them responded to Jesus by inviting others to come and see.</p>","tags":["type-article"]},{"location":"articles/John_1_35-51_Jesus_Connecting_Heaven_and_Earth.html#a-chain-reaction-of-testimony","title":"A Chain Reaction of Testimony","text":"<p>The structure of John 1:29-51</p> <p>This passage starts with \"the next day\". John first used this phrase earlier in John 1:29 when John the Baptist saw Jesus coming toward him and started testifying about Him. The next day, John points out Jesus again, and two of John's disciples follow Jesus. The next day, Jesus calls Philip to follow him. John seems to be using \"the next day\" to structure his narrative in John 1:29-51.</p> <p>John the Baptist again called Jesus the Lamb of God. At this, Andrew and another of John's disciples decided to follow Jesus, asking Him where He is staying. Jesus' response is to \"come and see\". Jesus invites them to come with Him and see where He is staying and what He is doing. Jesus is inviting them to join Him, to follow Him.</p> <p>After spending the day with Jesus, Andrew decided to tell his brother Simon that they had found the Messiah. Simon became the third to follow Jesus, who nicknamed him Peter. </p> <p>The next day, Jesus calls Philip to \"follow Me.\" Philip becomes the first disciple in John's Gospel to be directly called by Jesus. He is probably the fourth to follow Jesus.</p> <p>Like Andrew, Philip could not stay quiet about the Messiah, and he went and found Nathanael and told him about Jesus. Nathanael was not as quick to follow Jesus though, questioning if anything good can come from Nazareth.</p>","tags":["type-article"]},{"location":"articles/John_1_35-51_Jesus_Connecting_Heaven_and_Earth.html#the-first-testimonies","title":"The First Testimonies","text":"<p>These early followers gave Jesus several titles: - Lamb of God (John the Baptist) - Rabbi (the two disciples) - Messiah (Andrew) - the One Moses wrote about (Philip)  - the One the prophets foretold (Philip) - Jesus of Nazareth, the son of Joseph (Philip)</p> <p>Jesus gave himself titles too: - Son of Man (Daniel 7) - The ladder to heaven (Genesis 28 allusion)</p> <p>Just think about this: in this passage, we are told that Jesus is both a man and God. He is the fulfillment of the Jewish sacrificial system and the ladder connecting men to God. He was prophesied about by Moses, Daniel, and all the prophets.</p> <p>Each of these testimonies reveals something true about Jesus, but not everyone responded the same way.</p>","tags":["type-article"]},{"location":"articles/John_1_35-51_Jesus_Connecting_Heaven_and_Earth.html#different-people-different-paths","title":"Different People, Different Paths","text":"<p>It is interesting that different people responded differently when they heard about Jesus. </p> <p>Andrew, Peter, Philip, and the unnamed disciple follow immediately. They are quick to believe after hearing about Jesus.</p> <p>But Nathanael was more hesitant.  When Nathanael meets Him, Jesus calls Nathanael a \"true Israelite\", prompting Nathanael to ask, \"How do you know me?\". Jesus responds by telling him what he was doing before Philip called him. This was sufficient for Nathanael to change his mind and he believes Jesus is the Son of God and the King of Israel. </p> <p>No matter how skeptical or quick to believe, Jesus accepts all who believe.</p>","tags":["type-article"]},{"location":"articles/John_1_35-51_Jesus_Connecting_Heaven_and_Earth.html#testify-to-what-you-have-seen","title":"Testify to What You Have Seen","text":"<p>Jesus came as the ladder connecting people to the Father. But He doesn't personally call everyone like he did Philip. Instead His followers call people to Jesus, telling them about Him and encouraging them to check Him out for themselves.</p> <p>As disciples of Jesus, we too need to testify to what we have seen just as Andrew and Philip did. But our job is to testify, not to convince. When Nathanael didn't immediately believe Philip, he didn't argue. Instead he told Nathanael to \"come and see.\"</p> <p>But Jesus isn't here now for people to come and talk to. Instead we have the Bible and our personal experience. We have the arguments that convinced us. Our job isn't to convince anyone. It is to tell them what we have learned and what we believe. Our job is to be a witness, to testify to what we have seen. It is not to convince.</p> <p>But being a witness is not easy. Like Paul in his letter to the Ephesians, I want to regularly pray for courage. Not courage to win arguments, but to boldly share what I\u2019ve seen and believe about Jesus.</p> <p>Jesus is still inviting people to come and see. Now, He does it through us.</p>","tags":["type-article"]},{"location":"articles/John_1_35-51_Jesus_Connecting_Heaven_and_Earth.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"articles/John_6_Wrestling_With_The_Fathers_Drawing.html","title":"Wrestling with John 6: The Father, the Son, and the Struggle to Believe","text":"<p>John 6 has been one of the most difficult chapters for me to understand. It\u2019s packed with signs, huge crowds, grumbling, confusion, and eventually, a lot of people walking away from Jesus. But what really made me stop and wrestle with it was how Jesus talks about the Father\u2019s role in people coming to Him, and what that means for belief.</p> <p>Jesus says:</p> <ul> <li> <p>\"Everyone the Father gives Me will come to Me\" (John 6:37)</p> </li> <li> <p>\"No one can come to Me unless the Father who sent Me draws him\" (6:44)</p> </li> <li> <p>\"No one can come to Me unless it has been granted to him by the Father\" (6:65)</p> </li> </ul> <p>Then, in the same chapter, He says:</p> <ul> <li> <p>\"Everyone who looks to the Son and believes in Him shall have eternal life\" (6:40)</p> </li> <li> <p>\"Everyone who has heard and learned from the Father comes to Me\" (6:45)</p> </li> <li> <p>\"He who believes has eternal life\" (6:47)</p> </li> </ul> <p>These two sets of statements felt like they were pulling in opposite directions. On one hand, it sounds like we can\u2019t come to Jesus at all unless God does something first. On the other, belief seems to be the key to receiving eternal life. So I asked: Is Jesus saying that we can\u2019t believe unless the Father first draws us? And if that\u2019s true, does belief depend entirely on something God does beforehand?</p>","tags":["type-article"]},{"location":"articles/John_6_Wrestling_With_The_Fathers_Drawing.html#a-timeless-truth-applied-in-a-moment-of-unbelief","title":"A Timeless Truth Applied in a Moment of Unbelief","text":"<p>As I sat with these verses longer, I started to see that Jesus is teaching something timeless about how salvation works, and at the same time He's applying it to this specific group of people who were rejecting Him. The crowd had seen the miracle of the loaves and fishes, but they missed what the sign was pointing to: Jesus as the Bread of Life. When He taught them hard things, like eating His flesh and drinking His blood, many of them grumbled and walked away.</p> <p>Jesus doesn\u2019t chase after them or soften His teaching. Instead, He explains why they\u2019re leaving: they haven\u2019t truly heard or learned from the Father.</p> <p>Jesus says that everyone who hears and learns from the Father comes to Him (6:45). That means those who come are the ones the Father has drawn and given to the Son. And those who don\u2019t come are those who haven\u2019t responded rightly to the Father\u2019s teaching. This isn\u2019t mechanical or automatic. It\u2019s relational. It shows that true belief is a response to God\u2019s initiative.</p>","tags":["type-article"]},{"location":"articles/John_6_Wrestling_With_The_Fathers_Drawing.html#what-does-it-mean-to-hear-and-learn-from-the-father","title":"What Does It Mean to Hear and Learn from the Father?","text":"<p>That led to more questions. If hearing and learning from the Father leads to belief in Jesus, what does that actually involve? Is it just being exposed to a Bible verse or hearing a sermon? That didn\u2019t seem to fit.</p> <p>I think it means something more active. It means listening with an open mind and heart. Being willing to ask hard questions. Struggling to understand. Being honest. Wrestling with ideas that don\u2019t make sense right away. It means not tuning out.</p> <p>And learning from the Father doesn\u2019t mean we figure it out on our own. It\u2019s not about being smart or moral or religious. It\u2019s about being teachable. God is the one teaching. We choose whether to engage or ignore it.</p> <p>So this kind of hearing and learning isn\u2019t earning salvation. It\u2019s the opposite. It\u2019s repenting: turning away from whatever we thought would save us, and turning toward Jesus. Believing in who He is and what He has done.</p>","tags":["type-article"]},{"location":"articles/John_6_Wrestling_With_The_Fathers_Drawing.html#god-initiates-we-respond","title":"God Initiates. We Respond.","text":"<p>Thinking about Acts helped a lot. Cornelius and Lydia were both already seeking God before Peter and Paul shared the gospel with them. Paul himself, though completely wrong about Jesus, was zealously trying to serve God when Jesus confronted him.</p> <p>In every case, God took the first step: sending the message, opening hearts, intervening. But people still had to respond. That helped me see that God\u2019s initiative and human response are not at odds. They go together.</p> <p>God draws, grants, teaches, gives. But He doesn\u2019t force. Those who respond to the Father\u2019s teaching come to Jesus. Those who reject Jesus reveal that they were never truly listening to the Father.</p>","tags":["type-article"]},{"location":"articles/John_6_Wrestling_With_The_Fathers_Drawing.html#why-this-matters","title":"Why This Matters","text":"<p>Even though I am already a believer, this changed how I think about three key parts of following Jesus:</p>","tags":["type-article"]},{"location":"articles/John_6_Wrestling_With_The_Fathers_Drawing.html#evangelism-speak-boldly-trust-god-be-patient","title":"Evangelism: Speak Boldly, Trust God, Be Patient","text":"<p>I'm beginning to see how crucial evangelism really is. If no one shares the good news, how can people even begin to hear and learn from God? But even as we speak, we need to remember that we aren't the ones saving people. God is the one teaching. The other person is responsible for how they respond.</p> <p>That takes the pressure off. Evangelism isn't about winning arguments or closing deals. It's about bearing witness to what Jesus has done. We speak clearly and passionately, and then trust that God is working through our words to help others hear and learn and believe.</p>","tags":["type-article"]},{"location":"articles/John_6_Wrestling_With_The_Fathers_Drawing.html#discipleship-were-never-done-learning","title":"Discipleship: We're Never Done Learning","text":"<p>Believing in Jesus is not the finish line. It's the beginning. We continue to hear and learn from the Father as we follow Jesus day by day. Discipleship is a lifelong process of transformation.</p> <p>We won't always understand everything right away. That's okay. The point is to keep listening, keep learning, keep growing. Faith isn't static. It's dynamic.</p>","tags":["type-article"]},{"location":"articles/John_6_Wrestling_With_The_Fathers_Drawing.html#gods-word-the-primary-way-god-teaches","title":"God's Word: The Primary Way God Teaches","text":"<p>There are many ways God can speak to us\u2014through people, circumstances, even conscience. But the primary way God teaches His disciples is through His Word.</p> <p>If we want to hear and learn from the Father, we need to read and study Scripture. We need to sit under sound teaching. We need to engage with what God has already revealed. Scripture isn't just information. It's the voice of the living God, speaking to His people.</p> <p>See Inductive Bible Study Method to learn how I approach scripture.</p>","tags":["type-article"]},{"location":"articles/John_6_Wrestling_With_The_Fathers_Drawing.html#final-thoughts","title":"Final Thoughts","text":"<p>John 6 has been a tough chapter for me. But the more I wrestled with it, the more it started to make sense. Belief in Jesus isn\u2019t something I can manufacture. It\u2019s a response to what God is doing. At the same time, I\u2019m responsible for how I respond.</p> <p>Some walked away from Jesus because they couldn\u2019t accept what He was saying. Others stayed, even without fully understanding, because they trusted Him. I want to be in that second group.</p> <p>If I want to follow Jesus, I have to keep hearing and learning from the Father. Not once, but over and over again, for the rest of my life.</p>","tags":["type-article"]},{"location":"articles/John_6_Wrestling_With_The_Fathers_Drawing.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"articles/John_Author_and_recipients.html","title":"Who Wrote the Gospel of John, and Why Does It Matter?","text":"<p>John's Gospel feels different: it opens with poetry, it contains Jesus' teachings, and it contains signs that we might believe.</p> <p>But who wrote it? And who was it for?</p> <p>These questions matter. Not just for understanding the text, but for understanding its heart. This isn\u2019t just a biography of Jesus. It is testimony. Someone who walked with Jesus wanted you to know what he saw.</p>","tags":["type-article"]},{"location":"articles/John_Author_and_recipients.html#a-personal-voice","title":"A Personal Voice","text":"<p>The early church believed the author was John the Apostle. He was one of the Twelve and part of Jesus' inner circle. Early believers like Irenaeus and Clement of Alexandria say John wrote later in life, most likely from Ephesus.</p> <p>But John never names himself. Instead, he calls himself \"the disciple whom Jesus loved.\" That feels deeply personal. Like someone writing from memory, not from theory.</p> <p>Some scholars think others helped shape the final form of the Gospel. Maybe students or followers of John. I don't know if that is true or not. Paul used scribes to write his letters, so that possibility does not water it down. It reminds us: this Gospel came from a community that cherished what John saw.</p>","tags":["type-article"]},{"location":"articles/John_Author_and_recipients.html#a-life-that-lingered","title":"A Life That Lingered","text":"<p>John lived a long time. While Peter and Paul were martyred, tradition says John survived into old age. That longevity matters. It gave him time to reflect.</p> <p>John had been there from the beginning. Mending nets by the Sea of Galilee. Sitting beside Jesus at the Last Supper. Standing at the foot of the cross. Encountering Jesus after the resurrection. Later, he became a pillar in the church. He spent years teaching and mentoring in Ephesus.</p> <p>John did not just remember what Jesus did. He remembered what it meant.</p>","tags":["type-article"]},{"location":"articles/John_Author_and_recipients.html#why-so-late","title":"Why So Late?","text":"<p>Most scholars agree John\u2019s Gospel was written after the others. Likely between 85 and 95 AD. That does not make it less trustworthy. It makes it more reflective. Regardless of the number of years, John was an eye witness to these events.</p> <p>You can hear it in the way John writes. He does not just tell you what happened. He tells you why it matters. The Word became flesh. The signs point to Jesus' glory, leading to belief. Jesus reveals the Father.</p> <p>And we have good evidence that his Gospel was circulating early. A small Greek fragment of John (called the Rylands Papyrus) dates to the early 100s AD. So it had to be written before then.</p>","tags":["type-article"]},{"location":"articles/John_Author_and_recipients.html#a-subtle-response-to-heresy","title":"A Subtle Response to Heresy?","text":"<p>John insists that Jesus was fully human and fully divine. He got tired. He wept. He asked for water. And yet, He said, \"Before Abraham was, I am.\"</p> <p>This led me to wonder if John was responding to early Gnostic ideas. Beliefs that would later deny the goodness of the physical world or the possibility of God becoming flesh. My conclusion? Maybe. Those ideas were gaining steam in John\u2019s region.</p> <p>But John does not sound like he is writing a rebuttal. He sounds like he is offering a witness. The kind that says, \"I saw Him. I heard Him. I knew Him. I want you to know Him, too.\"</p>","tags":["type-article"]},{"location":"articles/John_Author_and_recipients.html#who-was-he-writing-to","title":"Who Was He Writing To?","text":"<p>John never says. He does not name a church or city like Paul does. But tradition says he spent his last years in Ephesus. A major city in Asia Minor. If that is true, maybe he had those believers in mind.</p> <p>And here is where it gets interesting. John writes:</p> <p>\"These are written so that you may believe that Jesus is the Christ, the Son of God, and that by believing you may have life in his name\" (John 20:31).</p> <p>That sounds evangelistic. Was he writing to unbelievers?</p> <p>Maybe. But Ephesus was full of believers too. Some young, some weary, some drifting.</p> <p>In fact, when Jesus later addresses the Ephesian church in Revelation, He says:</p> <p>\"You have forsaken the love you had at first.\"</p> <p>That was after John wrote, but it might hint at something already starting. Were they forgetting what they first believed?</p> <p>So maybe John was writing to both kinds of people: the seekers and the saints.</p>","tags":["type-article"]},{"location":"articles/John_Author_and_recipients.html#a-living-invitation","title":"A Living Invitation","text":"<p>John does not just want us to know Jesus. He wants us to believe in Him. And not just once. Continually.</p> <p>The Greek word he uses, pisteu\u0113te, can mean \"so that you may believe\" or \"so that you may keep on believing.\" Both make sense.</p> <p>This Gospel is an invitation. To believe and to keep believing. To return when you fail; just look at how Jesus restored Peter.</p> <p>The Word became flesh and dwelt among us.</p> <p>That is not just theology. That is personal.</p> <p>If your faith has gone cold, John wants to warm it. He wrote so you would remember who Jesus really is.</p> <p>The Word. The Light. The Son. The Lamb. The Shepherd. The Resurrection. The Life.</p> <p>\"These are written so that you may believe... and that by believing you may have life in His name.\"</p> <p>That is not just for the first readers. That is for us.</p>","tags":["type-article"]},{"location":"articles/John_Author_and_recipients.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"articles/John_Purpose.html","title":"Why Did John Write This Gospel?","text":"<p>John actually tells us, right near the end of his Gospel (John 20:30\u201331):</p> <p>Jesus performed many other signs in the presence of His disciples, which are not written in this book. But these are written so that you may believe that Jesus is the Christ, the Son of God, and that by believing you may have life in His name. </p> <p>So, why did John write this book? He chose specific signs and stories to include because he believed they were enough to help his readers believe. He could have written a lot more, but what he included was intentional and purposeful. His goal was clear: that we would believe.</p>","tags":["type-article"]},{"location":"articles/John_Purpose.html#what-does-john-want-us-to-believe","title":"What Does John Want Us to Believe?","text":"<p>John\u2019s message centers on one big idea: that Jesus is the Christ, the Son of God.</p> <p>First, John wants us to believe that Jesus is the Christ. \u201cChrist\u201d is the Greek word for \u201cMessiah,\u201d the promised one from the Old Testament. The Messiah was someone the Israelites had been waiting for: a king like David, a prophet like Moses, and the suffering servant Isaiah described. This was the one who would establish God's eternal kingdom. John is saying Jesus is that person.</p> <p>Second, John wants us to believe that Jesus is the Son of God. This wasn\u2019t just a poetic or honorary title. In Jesus\u2019 time, calling someone the Son of God was understood to mean they were claiming to be equal with God. And John wants to make it clear that Jesus is God, living among us as a human.</p> <p>All throughout his Gospel, John presents evidence for both of these claims. He\u2019s not just telling stories. He\u2019s building a case.</p>","tags":["type-article"]},{"location":"articles/John_Purpose.html#why-does-john-want-us-to-believe","title":"Why Does John Want Us to Believe?","text":"<p>Because believing leads to life.</p> <p>John says it plainly: he wants his readers to believe so that they may have life in Jesus' name. If belief leads to life, then the opposite is also true, namely, without belief, there is no life. John makes that contrast clear in his Gospel, showing what\u2019s at stake.</p>","tags":["type-article"]},{"location":"articles/John_Purpose.html#who-is-john-writing-to","title":"Who Is John Writing To?","text":"<p>John never comes right out and says who his audience is, but we can make some educated guesses.</p> <p>Maybe he was writing to:</p> <p>Believers, to encourage and strengthen their faith.</p> <p>Israelites, to convince them that Jesus really is the Messiah they\u2019d been waiting for.</p> <p>Unbelievers, to help them come to faith in Jesus.</p> <p>Which is it? Honestly, it could be all of the above.</p> <p>Here\u2019s why I think John had a broad audience in mind. During that time, many Jewish believers had been forced out of Jerusalem and were now living among Gentiles. They were facing persecution and may have started to question whether they were believing the right thing. John\u2019s Gospel would have been a powerful encouragement to them.</p> <p>But John also includes stories like Jesus revealing Himself to the Samaritans, people outside of Israel, and telling them He is the Messiah. And he quotes John the Baptist saying Jesus is the one who \u201ctakes away the sin of the world,\u201d not just Israel.</p> <p>So, it seems John\u2019s message is meant for everyone. No matter your background, this Gospel is written to help you \"believe that Jesus is the Christ, the Son of God, and that by believing you can have life in His name.\"</p>","tags":["type-article"]},{"location":"articles/John_Purpose.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"articles/Observe_what_this_passage_says.html","title":"Observe what this passage says","text":"<p>The first step in studying the Bible is observation: carefully examining the text to understand what it says. This means spending time with the passage, reading it multiple times. Fifteen to 20 readings is a good target. Don\u2019t rush. Let the text speak to you through repetition and familiarity.</p> <p>It\u2019s also important to read the passage according to its genre. Poetry, narrative, prophecy, and epistles all follow different patterns and styles, and recognizing this helps you read appropriately. Unless the genre suggests otherwise, read the passage as a complete unit. For example, in a book of poems or short stories, each section might stand alone. But in most cases, the author wrote the passage with a purpose in mind, and it's respectful, as well as wise, to read it in the way they intended.</p> <p>As you read, make a conscious effort to come to terms with the author. This means paying attention to the specific words and phrases they used, and asking what those terms meant to the author and the original audience, not just what they mean to you today. Our modern understanding of a word might not match the original intent. Look for how the author defines their terms within the text. Use multiple translations to see how different people at different times translated the passage, and when needed, consult tools for studying the original Hebrew or Greek to clarify meanings. Be alert for idioms or cultural expressions that might not translate clearly into English. Pay attention to where your Understanding presuppositions in Bible study are imposing meaning to the author's terms that the author did not intend.</p> <p>Throughout your study, maintain a careful discipline: don\u2019t add to Scripture, and don\u2019t take away from it. Let the text speak for itself. Keep every passage in its context. Avoid building an entire theology on a single verse, and resist the temptation to force a passage to fit your existing theology. Use simple and clear passages to understand complex and obscure passages. Don't let a possible understanding of a difficult passage force you to complicate a straight forward passage. Let the author's message shape your understanding, not the other way around.</p> <p>Remember, similar words or phrases don\u2019t always mean the same thing, even when used by the same author. Meaning depends on context, and it\u2019s possible for identical words to carry different nuances depending on when and how they\u2019re used.</p> <p>As you observe the passage, write down everything you notice. Be detailed and include even the obvious. This helps you avoid relying on assumptions or skipping over key details. Observation is about seeing what's really there, not what you expect to see.</p> <p>Finally, ask lots of questions. Curiosity is essential to good Bible study. Try to answer as many questions as you can from the passage itself. Consider: Who is the author? Who was the original audience? Who is speaking in this passage, and to whom are they speaking? These may not always be the same person or group. Also consider the historical and cultural background. What was happening at that time? What events had already taken place, or not yet happened, within the timeline of the narrative?</p> <p>By approaching Scripture with open eyes and an inquisitive heart, you give yourself the best chance to hear what it truly says.</p>","tags":["type-article"]},{"location":"articles/Observe_what_this_passage_says.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"articles/Understanding_Presuppositions_in_Bible_Study.html","title":"Understanding presuppositions in Bible study","text":"<p>In mathematics, foundational beliefs are called axioms. For example, one axiom says, \u201cThe shortest distance between two points is a straight line.\u201d Mathematicians use axioms like these to build logical arguments and prove more complex ideas.</p> <p>In the same way, we all bring certain assumptions, or presuppositions, when we read and study the Bible. It\u2019s natural. But when it comes to Scripture, we should try to be aware of these presuppositions and limit them as much as possible. Otherwise, they can distort our understanding.</p>","tags":["type-article"]},{"location":"articles/Understanding_Presuppositions_in_Bible_Study.html#my-starting-assumptions","title":"My Starting Assumptions","text":"<p>Here are the presuppositions I bring into Bible study\u2014these aren't baseless opinions, but conclusions I\u2019ve reached through previous study and reflection:</p> <ol> <li>God exists.</li> <li>God does not and cannot lie.</li> <li>Scripture, in its original form, was given by God.</li> <li>The copies of Scripture we have today reflect the original writings with high accuracy.</li> <li>Most English translators have genuinely tried to translate the Bible faithfully from the original languages.</li> </ol> <p>From these foundational beliefs, I conclude:</p> <ol> <li>Scripture is true.</li> <li>English Bible translations are generally trustworthy.</li> <li>Comparing different English translations is valuable.</li> <li>Understanding the original Hebrew and Greek is also helpful.</li> </ol>","tags":["type-article"]},{"location":"articles/Understanding_Presuppositions_in_Bible_Study.html#presuppositions-to-be-careful-with","title":"Presuppositions to Be Careful With","text":"<p>While it\u2019s okay to have some foundational beliefs, we must be cautious not to assume too much, especially about complex or controversial topics. Instead of starting with our own assumptions, we should let Scripture define these ideas for us.</p> <p>Avoid bringing assumptions into your reading about topics like:</p> <ul> <li>Free will</li> <li>God's will</li> <li>God's sovereignty</li> <li>Salvation</li> <li>The gospel (good news)</li> <li>Election</li> <li>Predestination</li> <li>God\u2019s foreknowledge</li> <li>The Chosen</li> <li>Atonement</li> <li>God\u2019s character</li> <li>Faith</li> <li>Belief</li> <li>Repentance</li> <li>Heaven</li> <li>Hell</li> <li>The Kingdom of Heaven</li> <li>The Kingdom of God</li> <li>Adoption</li> </ul> <p>Be careful not to assume that just because a word appears in different places in the Bible, it always means the same thing. Always consider how the author is using that word in the context of their message.</p> <p>Let Scripture speak for itself.</p>","tags":["type-article"]},{"location":"articles/Understanding_Presuppositions_in_Bible_Study.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-article"]},{"location":"notes/Atomic_Notes_Are_Not_Arguments.html","title":"Atomic Notes Are Not Arguments","text":"<p>An atomic note is not a full argument. Where an atomic note is a single concrete thought, an argument is structured reasoning. Since an atomic note is one single thought, it can be used in any number of arguments as needed. The goal is to capture an idea in a way that makes it reusable and composable across different contexts.</p> <ul> <li>How to Take Smart Notes</li> <li>Zettelkasten</li> <li>What an Atomic Note Is</li> <li>How Connecting Notes Generates Insight</li> <li>Writing is Thinking</li> </ul>","tags":["type-atomic"]},{"location":"notes/Atomic_Notes_Are_Not_Arguments.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-atomic"]},{"location":"notes/Everything_Iterates.html","title":"Everything iterates","text":"<p>It seems that everything in my life iterates. This note connects several areas of my life where iteration is the key to success.</p> <ul> <li>Note taking is an iterative process of creating notes, splitting notes, and connecting notes. See Writing is Iterative</li> <li>Software development iterates between product development and test development. #todo </li> <li>Bible study iterates between observation, interpretation and application. See Inductive Bible Study Method</li> <li> <p>The Scrum process iterates over sprints between planning, work, and feedback. #todo</p> </li> <li> <p>How Connecting Notes Generates Insight</p> </li> </ul>","tags":["type-atomic"]},{"location":"notes/Everything_Iterates.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-atomic"]},{"location":"notes/First_Sign_was_Turning_Water_to_Wine.html","title":"Jesus' First Sign was Turning Water to Wine","text":"<p>John identifies this miracle as Jesus\u2019 first sign at Cana. </p> <ul> <li>Signs in John</li> <li>John_2_1-11_The_Wedding_at_Cana</li> </ul>","tags":["type-atomic","bible-observation","the-wedding-at-cana"]},{"location":"notes/First_Sign_was_Turning_Water_to_Wine.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-atomic","bible-observation","the-wedding-at-cana"]},{"location":"notes/Galilean_weddings_were_multi-day_communal_events.html","title":"Galilean weddings were multi-day communal events","text":"<ul> <li>John_2_1-11_The_Wedding_at_Cana</li> <li>Running out of wine would shame the family</li> </ul>","tags":["type-atomic","bible-context","the-wedding-at-cana"]},{"location":"notes/Galilean_weddings_were_multi-day_communal_events.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-atomic","bible-context","the-wedding-at-cana"]},{"location":"notes/How_Connecting_Notes_Generates_Insight.html","title":"How Connecting Notes Generates Insight","text":"<p>Working on one note can unexpectedly clarify an idea in another. Insight often comes not from isolated thinking, but from the connections we make between notes. Connections come in many flavors. For example, this note builds on the idea that writing is iterative. Other notes might be a contrary opinion or a contrast. Sometimes, connections are between two seemingly unrelated topics. Revisiting and linking ideas reveals patterns we wouldn\u2019t see otherwise.</p> <ul> <li>How to Take Smart Notes</li> <li>Writing is Iterative</li> <li>Atomic Notes Are Not Arguments</li> </ul>","tags":["thinking","note-taking","writing-as-thinking","clarity-of-thought","connections"]},{"location":"notes/How_Connecting_Notes_Generates_Insight.html#example-connections","title":"Example Connections","text":"<ul> <li>Zettelkasten and Inductive Bible Study</li> <li>Everything iterates</li> </ul>","tags":["thinking","note-taking","writing-as-thinking","clarity-of-thought","connections"]},{"location":"notes/How_Connecting_Notes_Generates_Insight.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["thinking","note-taking","writing-as-thinking","clarity-of-thought","connections"]},{"location":"notes/Jesus_Reveals_His_Glory.html","title":"Jesus Reveals His Glory","text":"<p>In the last verse of this passage John states, \"He thus revealed His glory, and His disciples believed in Him.\"</p> <ul> <li>Jesus' First Sign was Turning Water to Wine</li> <li>Signs in John</li> </ul>","tags":["type-atomic","bible-observation","the-wedding-at-cana"]},{"location":"notes/Jesus_Reveals_His_Glory.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-atomic","bible-observation","the-wedding-at-cana"]},{"location":"notes/Nazareth_is_Close_to_Cana.html","title":"Nazareth is &lt;10 miles from Cana, explaining Mary\u2019s connection","text":"<ul> <li>John_2_1-11_The_Wedding_at_Cana</li> <li>Running out of wine would shame the family</li> </ul>","tags":["type-atomic","bible-context","the-wedding-at-cana"]},{"location":"notes/Nazareth_is_Close_to_Cana.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-atomic","bible-context","the-wedding-at-cana"]},{"location":"notes/Running_Out_of_Wine_at_a_Galilean_Wedding_was_Shameful.html","title":"Running out of wine would shame the family","text":"<ul> <li>John_2_1-11_The_Wedding_at_Cana</li> <li>Galilean weddings were multi-day communal events</li> </ul>","tags":["type-atomic","bible-context","the-wedding-at-cana"]},{"location":"notes/Running_Out_of_Wine_at_a_Galilean_Wedding_was_Shameful.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-atomic","bible-context","the-wedding-at-cana"]},{"location":"notes/The_Wedding_at_Cana_flow.html","title":"The Wedding at Cana - Story Flow","text":"<ol> <li>Jesus attends a wedding in Cana with His mother and disciples.</li> <li>The hosts run out of wine, a social disgrace in Galilean weddings.</li> <li>Mary tells Jesus about the problem; He replies that His \u201chour\u201d has not yet come.</li> <li>Jesus calls His mother \u201cwoman,\u201d a formal and polite address.</li> <li>Mary instructs the servants to obey Jesus.</li> <li>Six stone jars, each 20\u201330 gallons, are available for ceremonial washing.</li> <li>Jesus instructs the servants to fill the jars with water and present it to the master of the banquet.</li> <li>Jesus produces an estimated 120\u2013180 gallons of wine.</li> <li>The water becomes wine; only the servants and disciples are aware of the miracle.</li> <li> <p>The master of the banquet praises the bridegroom for serving the best wine last.</p> </li> <li> <p>John_2_1-11_The_Wedding_at_Cana</p> </li> <li>The Gospel of John</li> </ol>","tags":["type-structural","bible-observation","story-flow","the-wedding-at-cana"]},{"location":"notes/The_Wedding_at_Cana_flow.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-structural","bible-observation","story-flow","the-wedding-at-cana"]},{"location":"notes/What_an_Atomic_Note_Is.html","title":"What an Atomic Note Is","text":"<p>Atomic notes are meant to be kept forever. They contain all relevant information in themselves, including references to sources and links to related notes. They express a single, fully developed idea and should be written in complete sentences as if someone else was going to read them, including future you. It is important that atomic notes capture the full, complete idea so that when returning to the note it contains everything needed to understand it. They are not reminders of thoughts or ideas; they are the thoughts and ideas.</p> <ul> <li>How to Take Smart Notes</li> <li>Zettelkasten</li> <li>Atomic Notes Are Not Arguments</li> </ul>","tags":["type-atomic"]},{"location":"notes/What_an_Atomic_Note_Is.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-atomic"]},{"location":"notes/Writing_is_Iterative.html","title":"Writing is Iterative","text":"<p>Writing is an iterative process. As we revise our notes, we discover gaps in our understanding. Revising notes can take days or weeks as we return to the same ideas with fresh eyes. Notes are never truly \"done\". We can revise them anytime our understanding deepens.</p> <ul> <li>How to Take Smart Notes</li> <li>Writing is Thinking</li> </ul>","tags":["thinking","note-taking","writing-as-thinking","clarity-of-thought","iterative-process"]},{"location":"notes/Writing_is_Iterative.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["thinking","note-taking","writing-as-thinking","clarity-of-thought","iterative-process"]},{"location":"notes/Writing_is_Thinking.html","title":"Writing is Thinking","text":"<p>Writing is thinking. Writing isn't just recording our completed thoughts. We don't think and then write. It is the process for developing our ideas. When we write, we have to turn our thoughts into words. Thoughts start out as vague ideas in our heads. The process of writing requires us to slow down. This let's us articulate the idea in our own words so that it becomes a concise, accurate, and understandable atomic thought.</p> <ul> <li>How to Take Smart Notes</li> <li>What an Atomic Note Is</li> </ul>","tags":["thinking","note-taking","writing-as-thinking","clarity-of-thought"]},{"location":"notes/Writing_is_Thinking.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["thinking","note-taking","writing-as-thinking","clarity-of-thought"]},{"location":"notes/Zettelkasten_and_Inductive_Bible_Study.html","title":"Zettelkasten and Inductive Bible Study","text":"<p>The Zettelkasten note taking system works nicely with Inductive Bible Study. I start by taking quick notes of my observations, which I soon turn into atomic notes. From those observation notes, I build my interpretation as separate atomic notes linked back to the observations. I then create new atomic notes for application ideas.</p> <ul> <li>Inductive Bible Study Method</li> <li>Zettelkasten</li> </ul>","tags":["type-atomic"]},{"location":"notes/Zettelkasten_and_Inductive_Bible_Study.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-atomic"]},{"location":"notes/first_sign_reveals_jesus_glory_disciples_believe.html","title":"First sign reveals Jesus\u2019 glory; disciples believe","text":"<p>When Jesus turned water into wine He revealed His glory, deepening His disciples' faith.</p> <ul> <li>Jesus Reveals His Glory</li> <li>Jesus' First Sign was Turning Water to Wine</li> </ul>","tags":["the-wedding-at-cana","type-atomic","theology","bible-interpretation"]},{"location":"notes/first_sign_reveals_jesus_glory_disciples_believe.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["the-wedding-at-cana","type-atomic","theology","bible-interpretation"]},{"location":"notes/marys_faith_precedes_public_ministry.html","title":"Mary's faith precedes public ministry","text":"<p>When Mary saw that the wine had run out, she requested that Jesus help out. Despite Jesus' reply that \"My hour has not yet come\", Mary told the servants to \"Do whatever He tells you\". </p> <p>This demonstrates Mary's faith in Jesus in two ways: 1. She had faith that Jesus could help provide more wine 2. She had faith that Jesus would help even if He wasn't ready to reveal Himself publicly</p> <ul> <li>The Wedding at Cana - Story Flow</li> <li>Semi-private miracle: Glory revealed selectively</li> </ul>","tags":["the-wedding-at-cana","bible-interpretation","type-atomic"]},{"location":"notes/marys_faith_precedes_public_ministry.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["the-wedding-at-cana","bible-interpretation","type-atomic"]},{"location":"notes/semi-private_miracle_glory_revealed_selectively.html","title":"Semi-private miracle: Glory revealed selectively","text":"<p>When Jesus turned water into wine His hour had not yet come. So while He performed the miracle His mother requested, he did so semi-privately. This allowed him to reveal His glory more selectively and not draw as much attention to Himself.</p> <ul> <li>The Wedding at Cana - Story Flow</li> <li>First sign reveals Jesus\u2019 glory; disciples believe</li> </ul>","tags":["type-atomic","bible-interpretation","the-wedding-at-cana"]},{"location":"notes/semi-private_miracle_glory_revealed_selectively.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-atomic","bible-interpretation","the-wedding-at-cana"]},{"location":"notes/signs_in_john_lead_to_faith.html","title":"Signs in the Gospel of John Lead to Faith","text":"<p>John chose the signs he included in his gospel specifically to lead his readers to faith. </p> <ul> <li>First sign reveals Jesus\u2019 glory; disciples believe</li> <li>Signs in John</li> <li>Why Did John Write This Gospel?</li> </ul>","tags":["type-atomic","bible-interpretation"]},{"location":"notes/signs_in_john_lead_to_faith.html#linked-mentions","title":"Linked mentions","text":"<p>BACKLINK_PLUGIN_3671177_PLACEHOLDER</p>","tags":["type-atomic","bible-interpretation"]}]}